import React, { useState, useEffect, useCallback } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { supabaseService } from '../../../services/supabaseService';
import { updateAcademyTracksAsync } from '../../../store/contentSlice';
import Icon from '../../../components/AppIcon';
import { cn } from '../../../utils/cn';
import { useToast } from '../../../contexts/ToastContext';

const TrackAttendanceOverview = () => {
    const dispatch = useDispatch();
    const { addToast } = useToast();
    const academyTracks = useSelector((state) => state.content.academyTracks) || [];
    const [selectedTrackId, setSelectedTrackId] = useState('');
    const [students, setStudents] = useState([]);
    const [captains, setCaptains] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    const [isAssigning, setIsAssigning] = useState(false);
    const [error, setError] = useState('');
    const [refreshKey, setRefreshKey] = useState(0);
    const [trackSchedule, setTrackSchedule] = useState(null);
    const [scheduleSessions, setScheduleSessions] = useState([]);
    const [courseAttendanceData, setCourseAttendanceData] = useState({});

    const selectedTrack = academyTracks.find(t => String(t.id) === selectedTrackId);
    const trackCourseIdsString = selectedTrack?.courses?.join(',') || '';
    const trackCourseIds = React.useMemo(() => {
        return trackCourseIdsString ? trackCourseIdsString.split(',').map(String) : [];
    }, [trackCourseIdsString]);

    const loadStats = useCallback(async () => {
        if (!selectedTrackId || !trackCourseIds.length) {
            setStudents([]);
            setCaptains(null);
            setTrackSchedule(null);
            setScheduleSessions([]);
            setCourseAttendanceData({});
            return;
        }

        setIsLoading(true);
        setError('');
        try {
            const [data, caps, scheduleResult] = await Promise.all([
                supabaseService.getTrackAttendanceStatsForAllStudents(trackCourseIds),
                supabaseService.getTrackCaptains(trackCourseIds),
                supabaseService.getTrackScheduleWithAttendance(selectedTrackId, trackCourseIds).catch(() => ({ schedule: null, sessions: [], attendanceData: {} })),
            ]);
            setStudents(data);
            setCaptains(caps);
            setTrackSchedule(scheduleResult.schedule);
            setScheduleSessions(scheduleResult.sessions || []);
            setCourseAttendanceData(scheduleResult.attendanceData || {});
        } catch (err) {
            console.error('Failed to load track attendance stats:', err);
            setError('Failed to load attendance data. Please try again.');
        } finally {
            setIsLoading(false);
        }
    }, [selectedTrackId, trackCourseIds]);

    useEffect(() => {
        loadStats();
    }, [loadStats, refreshKey]);

    // Real-time: auto-refresh when attendance marks change or registers open/close
    useEffect(() => {
        if (!selectedTrackId || !trackCourseIds.length) return;

        const channel = supabaseService.client
            .channel('track_attendance_overview')
            .on(
                'postgres_changes',
                { event: '*', schema: 'public', table: 'lesson_progress' },
                () => { loadStats(); }
            )
            .on('broadcast', { event: 'ATTENDANCE_OPENED' }, () => { loadStats(); })
            .on('broadcast', { event: 'ATTENDANCE_CLOSED' }, () => { loadStats(); })
            .subscribe();

        return () => { supabaseService.client.removeChannel(channel); };
    }, [selectedTrackId, trackCourseIds, loadStats]);

    const handleAssignCaptains = async () => {
        if (!selectedTrack || !trackCourseIds.length) return;

        setIsAssigning(true);
        try {
            const assignedCaptains = await supabaseService.assignTrackCaptains(trackCourseIds);
            
            if (!assignedCaptains) {
                addToast('No eligible students found for this track.', 'error');
                return;
            }

            const updatedTracks = academyTracks.map(track => {
                if (String(track.id) === selectedTrackId) {
                    return { ...track, captains: assignedCaptains };
                }
                return track;
            });

            await dispatch(updateAcademyTracksAsync(updatedTracks)).unwrap();
            setCaptains(assignedCaptains);
            addToast('Track captains assigned successfully!', 'success');
        } catch (err) {
            console.error('Failed to assign captains:', err);
            addToast('Failed to assign captains. Please try again.', 'error');
        } finally {
            setIsAssigning(false);
        }
    };

    const meetsCount = students.filter(s => s.meetsRequirement).length;
    const totalCount = students.length;
    const avgPercentage = totalCount > 0 ? Math.round(students.reduce((a, s) => a + s.percentage, 0) / totalCount) : 0;

    return (
        <div className="space-y-6 p-4 md:p-6 overflow-hidden">
            <div>
                <h2 className="text-xl sm:text-2xl font-black italic text-primary">Track Attendance Overview</h2>
                <p className="text-sm text-muted-foreground mt-1">
                    View all students' attendance levels for a learning track. Students need at least 70% attendance to be eligible for graduation and certificates.
                </p>
            </div>

            {/* Track Selector */}
            <div className="p-4 sm:p-6 border border-border rounded-2xl bg-card space-y-4">
                <label className="block text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1">Select a Learning Track</label>
                <div className="flex gap-3">
                    <select
                        value={selectedTrackId}
                        onChange={e => setSelectedTrackId(e.target.value)}
                        className="flex-1 px-4 py-3 bg-muted border border-border rounded-xl text-sm outline-none focus:ring-2 focus:ring-primary"
                    >
                        <option value="">Choose a track...</option>
                        {academyTracks.filter(t => t?.courses?.length > 0).map(track => (
                            <option key={track.id} value={track.id}>{track.title} ({track.courses.length} courses)</option>
                        ))}
                    </select>
                    <button
                        onClick={() => setRefreshKey(k => k + 1)}
                        disabled={!selectedTrackId || isLoading}
                        className="px-6 py-3 bg-primary text-white font-bold rounded-xl text-sm hover:bg-primary/90 transition-all disabled:opacity-50 flex items-center gap-2"
                    >
                        {isLoading ? <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin" /> : <Icon name="RefreshCw" size={16} />}
                        Refresh
                    </button>
                </div>
                {selectedTrack && trackCourseIds.length > 0 && (
                    <div className="p-3 bg-muted/50 border border-border rounded-xl">
                        <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground mb-2">Track Courses ({trackCourseIds.length})</p>
                        <div className="flex flex-wrap gap-2">
                            {selectedTrack.courses.map(cId => (
                                <span key={cId} className="text-xs font-medium px-2 py-1 bg-card border border-border rounded-lg">{cId}</span>
                            ))}
                        </div>
                    </div>
                )}

                {/* Assign Captains Button */}
                {selectedTrack && trackCourseIds.length > 0 && (
                    <div className="flex flex-col sm:flex-row items-center gap-3 pt-2">
                        <button
                            onClick={handleAssignCaptains}
                            disabled={isAssigning}
                            className="px-6 py-3 bg-secondary text-white font-bold rounded-xl text-sm hover:bg-secondary/90 transition-all disabled:opacity-50 flex items-center gap-2"
                        >
                            {isAssigning ? (
                                <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                            ) : (
                                <Icon name="UserPlus" size={16} />
                            )}
                            {isAssigning ? 'Assigning...' : 'Assign Track Captains'}
                        </button>
                        <p className="text-xs text-muted-foreground">
                            Oldest student becomes Captain, Youngest becomes Assistant Captain
                        </p>
                    </div>
                )}
                
                {/* Captain Display */}
                {selectedTrack && captains && (
                    <div className="p-4 sm:p-5 bg-gradient-to-r from-secondary/5 to-primary/5 border border-primary/20 rounded-2xl flex flex-col sm:flex-row gap-6 mt-4">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-secondary/20 flex items-center justify-center border border-secondary/30 shrink-0">
                                <Icon name="Crown" size={20} className="text-secondary" />
                            </div>
                            <div>
                                <p className="text-[10px] font-bold uppercase tracking-widest text-secondary">Track Captain (Oldest)</p>
                                <p className="text-sm font-bold text-primary">{captains.captain.studentFullName} <span className="text-muted-foreground font-normal">({captains.captain.ageNum} yrs)</span></p>
                            </div>
                        </div>
                        {captains.assistantCaptain && (
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center border border-primary/20 shrink-0">
                                    <Icon name="Award" size={20} className="text-primary" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-bold uppercase tracking-widest text-primary">Assistant Captain (Youngest)</p>
                                    <p className="text-sm font-bold text-primary">{captains.assistantCaptain.studentFullName} <span className="text-muted-foreground font-normal">({captains.assistantCaptain.ageNum} yrs)</span></p>
                                </div>
                            </div>
                        )}
                        {captains.assignedAt && (
                            <div className="sm:ml-auto flex items-center">
                                <p className="text-[10px] text-muted-foreground">
                                    Assigned: {new Date(captains.assignedAt).toLocaleDateString()}
                                </p>
                            </div>
                        )}
                    </div>
                )}
            </div>

            {/* Track Schedule Status */}
            {selectedTrackId && trackSchedule && scheduleSessions.length > 0 && (
                <div className="p-4 sm:p-6 border border-border rounded-2xl bg-card">
                    <div className="flex items-center justify-between mb-3">
                        <h3 className="text-sm font-bold flex items-center gap-2">
                            <Icon name="Calendar" size={16} className="text-secondary" />
                            6-Week Course Schedule
                        </h3>
                        <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">
                            {scheduleSessions.length} sessions total
                        </span>
                    </div>
                    <div className="flex flex-wrap gap-2">
                        {scheduleSessions.map((s, i) => {
                            const now = new Date();
                            const sessionDate = new Date(s.date);
                            const isPast = sessionDate < new Date(now.getFullYear(), now.getMonth(), now.getDate());
                            const isToday = sessionDate.toISOString().split('T')[0] === now.toISOString().split('T')[0];

                            return (
                                <div key={i} className={`text-center py-1.5 px-2 rounded-lg text-[10px] border ${
                                    isToday ? 'bg-primary/10 border-primary/30 font-bold text-primary' :
                                    isPast ? 'bg-muted/50 border-border text-muted-foreground' :
                                    'bg-background border-border text-foreground'
                                }`}>
                                    <div className="font-bold">W{s.week}</div>
                                    <div>{s.date.slice(5)}</div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {error && (
                <div className="p-4 bg-red-500/10 border border-red-500/30 rounded-xl text-red-600 text-sm font-medium">{error}</div>
            )}

            {/* Summary Stats */}
            {students.length > 0 && (
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                    <div className="p-4 bg-card border border-border rounded-xl text-center">
                        <p className="text-3xl font-black text-primary">{totalCount}</p>
                        <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground mt-1">Total Students</p>
                    </div>
                    <div className="p-4 bg-card border border-border rounded-xl text-center">
                        <p className="text-3xl font-black text-emerald-600">{meetsCount}</p>
                        <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground mt-1">Meet 70% Requirement</p>
                    </div>
                    <div className="p-4 bg-card border border-border rounded-xl text-center">
                        <p className="text-3xl font-black text-secondary">{avgPercentage}%</p>
                        <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground mt-1">Average Attendance</p>
                    </div>
                </div>
            )}

            {/* Per-Course Attendance Breakdown */}
            {selectedTrackId && students.length > 0 && trackCourseIds.length > 1 && (
                <div className="p-4 sm:p-6 border border-border rounded-2xl bg-card">
                    <h3 className="text-sm font-bold mb-4 flex items-center gap-2">
                        <Icon name="BarChart2" size={16} className="text-secondary" />
                        Per-Course Attendance Breakdown
                    </h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                        {trackCourseIds.map(cId => {
                            const totalForCourse = students.reduce((acc, s) => {
                                const courseStats = s.courseStats?.find(cs => String(cs.courseId) === String(cId));
                                return acc + (courseStats?.total || 0);
                            }, 0);
                            const attendedForCourse = students.reduce((acc, s) => {
                                const courseStats = s.courseStats?.find(cs => String(cs.courseId) === String(cId));
                                return acc + (courseStats?.attended || 0);
                            }, 0);
                            const percentage = totalForCourse > 0 ? Math.round((attendedForCourse / totalForCourse) * 100) : 0;
                            const scheduledSessions = scheduleSessions.length || 18;

                            return (
                                <div key={cId} className="p-4 bg-muted/30 border border-border rounded-xl space-y-2">
                                    <p className="text-xs font-bold text-primary truncate">Course {cId}</p>
                                    <div className="flex items-center justify-between text-sm">
                                        <span className="text-muted-foreground font-medium">{attendedForCourse}/{totalForCourse} attended</span>
                                        <span className={`font-black ${percentage >= 70 ? 'text-emerald-600' : 'text-red-500'}`}>{percentage}%</span>
                                    </div>
                                    <div className="w-full h-1.5 bg-muted rounded-full overflow-hidden">
                                        <div className={`h-full rounded-full ${percentage >= 70 ? 'bg-emerald-500' : 'bg-red-500'}`} style={{ width: `${Math.min(percentage, 100)}%` }} />
                                    </div>
                                    {courseAttendanceData[String(cId)]?.length > 0 && (
                                        <p className="text-[10px] text-muted-foreground">
                                            {courseAttendanceData[String(cId)].length} session(s) opened
                                        </p>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Student List */}
            {isLoading ? (
                <div className="flex justify-center py-20">
                    <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
                </div>
            ) : students.length > 0 ? (
                <div className="border border-border rounded-2xl overflow-hidden bg-card">
                    {/* Mobile card layout */}
                    <div className="md:hidden divide-y divide-border">
                        {students.map(s => (
                            <div key={s.userId} className="p-4 space-y-3">
                                <div className="flex items-center gap-3">
                                    {s.avatarUrl ? (
                                        <img src={s.avatarUrl} alt="" className="w-10 h-10 rounded-full object-cover" />
                                    ) : (
                                        <div className="w-10 h-10 rounded-full bg-muted flex items-center justify-center text-xs font-black">
                                            {s.fullName?.charAt(0) || '?'}
                                        </div>
                                    )}
                                    <div className="min-w-0 flex-1">
                                        <p className="font-bold text-sm truncate flex items-center gap-2">
                                            {s.fullName}
                                            {captains?.captain?.user_id === s.userId && (
                                                <span title="Track Captain (Oldest)" className="bg-secondary/10 text-secondary border border-secondary/20 p-0.5 rounded-full inline-flex"><Icon name="Crown" size={12} /></span>
                                            )}
                                            {captains?.assistantCaptain?.user_id === s.userId && (
                                                <span title="Assistant Captain (Youngest)" className="bg-primary/10 text-primary border border-primary/20 p-0.5 rounded-full inline-flex"><Icon name="Award" size={12} /></span>
                                            )}
                                        </p>
                                        <p className="text-[10px] text-muted-foreground truncate">{s.email}</p>
                                    </div>
                                    <div className="shrink-0">
                                        {s.meetsRequirement ? (
                                            <span className="text-[10px] font-black uppercase tracking-wider text-emerald-600 bg-emerald-500/10 px-2 py-0.5 rounded-full">
                                                ✓ Eligible
                                            </span>
                                        ) : (
                                            <span className="text-[10px] font-black uppercase tracking-wider text-red-500 bg-red-500/10 px-2 py-0.5 rounded-full">
                                                {70 - s.percentage}% Needed
                                            </span>
                                        )}
                                    </div>
                                </div>
                                <div className="flex items-center justify-between text-xs">
                                    <span className="text-muted-foreground font-medium">{s.attended}/{s.total} sessions</span>
                                    <span className={cn('font-black', s.meetsRequirement ? 'text-emerald-600' : 'text-red-500')}>
                                        {s.percentage}%
                                    </span>
                                </div>
                                <div className="w-full h-2 bg-muted rounded-full overflow-hidden">
                                    <div
                                        className={cn('h-full rounded-full', s.meetsRequirement ? 'bg-emerald-500' : 'bg-red-500')}
                                        style={{ width: `${s.percentage}%` }}
                                    />
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Desktop table layout */}
                    <div className="hidden md:block overflow-x-auto">
                        <table className="w-full text-sm">
                            <thead>
                                <tr className="border-b border-border bg-muted/50">
                                    <th className="text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Student</th>
                                    <th className="text-center px-4 py-3 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Attended</th>
                                    <th className="text-center px-4 py-3 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Total Sessions</th>
                                    <th className="text-center px-4 py-3 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Percentage</th>
                                    <th className="text-center px-4 py-3 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Status</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-border">
                                {students.map(s => (
                                    <tr key={s.userId} className="hover:bg-muted/30 transition-colors">
                                        <td className="px-4 py-3">
                                            <div className="flex items-center gap-3">
                                                {s.avatarUrl ? (
                                                    <img src={s.avatarUrl} alt="" className="w-8 h-8 rounded-full object-cover" />
                                                ) : (
                                                    <div className="w-8 h-8 rounded-full bg-muted flex items-center justify-center text-[10px] font-black">
                                                        {s.fullName?.charAt(0) || '?'}
                                                    </div>
                                                )}
                                                <div className="min-w-0">
                                                    <p className="font-bold text-sm truncate flex items-center gap-2">
                                                        {s.fullName}
                                                        {captains?.captain?.user_id === s.userId && (
                                                            <span title="Track Captain (Oldest)" className="bg-secondary/10 text-secondary border border-secondary/20 p-0.5 rounded-full inline-flex"><Icon name="Crown" size={12} /></span>
                                                        )}
                                                        {captains?.assistantCaptain?.user_id === s.userId && (
                                                            <span title="Assistant Captain (Youngest)" className="bg-primary/10 text-primary border border-primary/20 p-0.5 rounded-full inline-flex"><Icon name="Award" size={12} /></span>
                                                        )}
                                                    </p>
                                                    <p className="text-[10px] text-muted-foreground truncate">{s.email}</p>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-4 py-3 text-center font-bold">{s.attended}</td>
                                        <td className="px-4 py-3 text-center font-bold">{s.total}</td>
                                        <td className="px-4 py-3 text-center">
                                            <div className="flex items-center gap-2 justify-center">
                                                <div className="w-16 h-1.5 bg-muted rounded-full overflow-hidden">
                                                    <div
                                                        className={cn('h-full rounded-full', s.meetsRequirement ? 'bg-emerald-500' : 'bg-red-500')}
                                                        style={{ width: `${s.percentage}%` }}
                                                    />
                                                </div>
                                                <span className={cn('text-xs font-black', s.meetsRequirement ? 'text-emerald-600' : 'text-red-500')}>
                                                    {s.percentage}%
                                                </span>
                                            </div>
                                        </td>
                                        <td className="px-4 py-3 text-center">
                                            {s.meetsRequirement ? (
                                                <span className="text-[10px] font-black uppercase tracking-wider text-emerald-600 bg-emerald-500/10 px-2 py-0.5 rounded-full">
                                                    ✓ Eligible
                                                </span>
                                            ) : (
                                                <span className="text-[10px] font-black uppercase tracking-wider text-red-500 bg-red-500/10 px-2 py-0.5 rounded-full">
                                                    {70 - s.percentage}% Needed
                                                </span>
                                            )}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            ) : selectedTrackId ? (
                <div className="py-20 text-center border border-dashed border-border rounded-2xl">
                    <Icon name="ClipboardList" size={48} className="mx-auto mb-4 text-muted-foreground/30" />
                    <p className="text-muted-foreground font-medium">No attendance data found for this track.</p>
                    <p className="text-xs text-muted-foreground mt-1">Students must mark attendance in track courses to appear here.</p>
                </div>
            ) : (
                <div className="py-20 text-center border border-dashed border-border rounded-2xl">
                    <Icon name="BarChart" size={48} className="mx-auto mb-4 text-muted-foreground/30" />
                    <p className="text-muted-foreground font-medium">Select a learning track above to view attendance levels.</p>
                </div>
            )}
        </div>
    );
};

export default TrackAttendanceOverview;
