import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import Select from '../../../components/ui/Select';
import { Checkbox } from '../../../components/ui/Checkbox';

const OpportunityManagementTable = ({ opportunities, onEdit, onDelete, onBulkAction, onToggleTrending, onAdd }) => {
  const [selectedItems, setSelectedItems] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');

  const statusOptions = [
    { value: 'all', label: 'All Status' },
    { value: 'active', label: 'Active' },
    { value: 'pending', label: 'Pending Review' },
    { value: 'draft', label: 'Draft' },
    { value: 'expired', label: 'Expired' }
  ];

  const filteredOpportunities = opportunities?.filter(opp => {
    const matchesSearch = opp?.title?.toLowerCase()?.includes(searchQuery?.toLowerCase()) ||
      opp?.category?.toLowerCase()?.includes(searchQuery?.toLowerCase());
    const matchesStatus = statusFilter === 'all' || opp?.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const handleSelectAll = (e) => {
    if (e?.target?.checked) {
      setSelectedItems(filteredOpportunities?.map(opp => opp?.id));
    } else {
      setSelectedItems([]);
    }
  };

  const handleSelectItem = (id) => {
    setSelectedItems(prev =>
      prev?.includes(id) ? prev?.filter(item => item !== id) : [...prev, id]
    );
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      active: { bg: 'bg-success/10', text: 'text-success', label: 'Active' },
      pending: { bg: 'bg-warning/10', text: 'text-warning', label: 'Pending' },
      draft: { bg: 'bg-muted', text: 'text-muted-foreground', label: 'Draft' },
      expired: { bg: 'bg-error/10', text: 'text-error', label: 'Expired' }
    };
    const config = statusConfig?.[status] || statusConfig?.draft;
    return (
      <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${config?.bg} ${config?.text}`}>
        {config?.label}
      </span>
    );
  };

  return (
    <div className="bg-card rounded-2xl shadow-[0_4px_12px_rgba(27,54,93,0.08)]">
      <div className="p-4 md:p-6 border-b border-border">
        <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-4 mb-4 animate-in fade-in duration-300">
          <h2 className="text-xl md:text-2xl font-bold text-foreground">Opportunity Management</h2>
          <div className="flex items-center gap-2">
            {selectedItems?.length > 0 && (
              <>
                <span className="text-sm text-muted-foreground">{selectedItems?.length} selected</span>
                <Button
                  variant="outline"
                  size="sm"
                  iconName="Trash2"
                  iconPosition="left"
                  onClick={() => onBulkAction?.('delete', selectedItems)}
                >
                  Delete
                </Button>
              </>
            )}
            {onAdd && (
              <Button
                variant="default"
                size="sm"
                iconName="Plus"
                iconPosition="left"
                onClick={onAdd}
              >
                Add Opportunity
              </Button>
            )}
          </div>
        </div>
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1">
            <Input
              type="search"
              placeholder="Search opportunities..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e?.target?.value)}
            />
          </div>
          <div className="w-full md:w-48">
            <Select
              options={statusOptions}
              value={statusFilter}
              onChange={setStatusFilter}
              placeholder="Filter by status"
            />
          </div>
        </div>
      </div>
      <div className="overflow-hidden">

        {/* Mobile Card View */}
        <div className="md:hidden divide-y divide-border">
          {filteredOpportunities?.map((opportunity) => (
            <div key={opportunity?.id} className="p-4 space-y-3">
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0 flex-1">
                  <div className="font-medium text-foreground line-clamp-1">{opportunity?.title}</div>
                  <div className="text-sm text-muted-foreground line-clamp-1">{opportunity?.organization}</div>
                </div>
                {getStatusBadge(opportunity?.status)}
              </div>
              <div className="flex items-center gap-3 text-sm text-muted-foreground">
                <span className="uppercase text-xs font-medium">{opportunity?.category}</span>
                <span>·</span>
                <span className="whitespace-nowrap">{opportunity?.deadline}</span>
                <span>·</span>
                <span className="flex items-center gap-1"><Icon name="Eye" size={14} />{opportunity?.views}</span>
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Checkbox
                    checked={selectedItems?.includes(opportunity?.id)}
                    onChange={() => handleSelectItem(opportunity?.id)}
                  />
                  <span className="text-xs text-muted-foreground">Trending</span>
                  <Checkbox
                    checked={opportunity?.trending}
                    onChange={() => onToggleTrending(opportunity?.id)}
                  />
                </div>
                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={(e) => { e.stopPropagation(); onEdit(opportunity?.id); }}
                    className="w-11 h-11 rounded-xl flex items-center justify-center hover:bg-muted transition-colors"
                    aria-label="Edit opportunity"
                  >
                    <Icon name="Edit2" size={18} color="var(--color-secondary)" />
                  </button>
                  <button
                    type="button"
                    onClick={(e) => { e.stopPropagation(); onDelete(opportunity?.id); }}
                    className="w-11 h-11 rounded-xl flex items-center justify-center hover:bg-muted transition-colors"
                    aria-label="Delete opportunity"
                  >
                    <Icon name="Trash2" size={18} color="var(--color-error)" />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Desktop Table View */}
        <div className="hidden md:block overflow-x-auto">
          <table className="w-full">
            <thead className="bg-muted/50">
              <tr>
                <th className="px-4 py-3 text-left">
                  <Checkbox
                    checked={selectedItems?.length === filteredOpportunities?.length && filteredOpportunities?.length > 0}
                    onChange={handleSelectAll}
                  />
                </th>
                <th className="px-4 py-3 text-left text-sm font-semibold text-foreground">Title</th>
                <th className="px-4 py-3 text-left text-sm font-semibold text-foreground">Category</th>
                <th className="px-4 py-3 text-left text-sm font-semibold text-foreground">Status</th>
                <th className="px-4 py-3 text-left text-sm font-semibold text-foreground text-center">Trending</th>
                <th className="px-4 py-3 text-left text-sm font-semibold text-foreground">Deadline</th>
                <th className="px-4 py-3 text-left text-sm font-semibold text-foreground">Views</th>
                <th className="px-4 py-3 text-right text-sm font-semibold text-foreground">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {filteredOpportunities?.map((opportunity) => (
                <tr key={opportunity?.id} className="hover:bg-muted/30 transition-colors">
                  <td className="px-4 py-4">
                    <Checkbox
                      checked={selectedItems?.includes(opportunity?.id)}
                      onChange={() => handleSelectItem(opportunity?.id)}
                    />
                  </td>
                  <td className="px-4 py-4">
                    <div className="font-medium text-foreground line-clamp-1">{opportunity?.title}</div>
                    <div className="text-sm text-muted-foreground line-clamp-1">{opportunity?.organization}</div>
                  </td>
                  <td className="px-4 py-4">
                    <span className="text-sm text-muted-foreground uppercase">{opportunity?.category}</span>
                  </td>
                  <td className="px-4 py-4">
                    {getStatusBadge(opportunity?.status)}
                  </td>
                  <td className="px-4 py-4 text-center">
                    <Checkbox
                      checked={opportunity?.trending}
                      onChange={() => onToggleTrending(opportunity?.id)}
                    />
                  </td>
                  <td className="px-4 py-4">
                    <span className="text-sm text-foreground whitespace-nowrap">{opportunity?.deadline}</span>
                  </td>
                  <td className="px-4 py-4">
                    <div className="flex items-center gap-1 text-sm text-muted-foreground">
                      <Icon name="Eye" size={16} />
                      <span>{opportunity?.views}</span>
                    </div>
                  </td>
                  <td className="px-4 py-4">
                    <div className="flex items-center justify-end gap-2">
                      <button
                        type="button"
                        onClick={(e) => { e.stopPropagation(); onEdit(opportunity?.id); }}
                        className="p-2 rounded-lg hover:bg-muted transition-colors"
                        aria-label="Edit opportunity"
                      >
                        <Icon name="Edit2" size={18} color="var(--color-secondary)" />
                      </button>
                      <button
                        type="button"
                        onClick={(e) => { e.stopPropagation(); onDelete(opportunity?.id); }}
                        className="p-2 rounded-lg hover:bg-muted transition-colors"
                        aria-label="Delete opportunity"
                      >
                        <Icon name="Trash2" size={18} color="var(--color-error)" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
      {filteredOpportunities?.length === 0 && (
        <div className="p-12 text-center">
          <Icon name="Search" size={48} color="var(--color-muted-foreground)" className="mx-auto mb-4" />
          <p className="text-muted-foreground">No opportunities found matching your criteria</p>
        </div>
      )}
    </div>
  );
};

export default OpportunityManagementTable;