import React from 'react';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';

const RecentActivityItem = ({ activity }) => {
  const getActivityIcon = (type) => {
    switch (type) {
      case 'opportunity':
        return 'Briefcase';
      case 'user':
        return 'UserPlus';
      case 'success':
        return 'Award';
      case 'community':
        return 'MessageCircle';
      default:
        return 'Activity';
    }
  };

  const getActivityColor = (type) => {
    switch (type) {
      case 'opportunity':
        return 'bg-secondary/10 text-secondary';
      case 'user':
        return 'bg-success/10 text-success';
      case 'success':
        return 'bg-accent/10 text-accent';
      case 'community':
        return 'bg-brand-purple/10 text-brand-purple';
      default:
        return 'bg-muted text-muted-foreground';
    }
  };

  return (
    <div className="flex items-start gap-4 p-4 rounded-xl hover:bg-muted/50 transition-colors duration-300">
      <div className={`w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0 ${getActivityColor(activity?.type)}`}>
        <Icon name={getActivityIcon(activity?.type)} size={20} />
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-start justify-between gap-2 mb-1">
          <p className="text-sm font-medium text-foreground">{activity?.title}</p>
          <span className="text-xs text-muted-foreground whitespace-nowrap">{activity?.time}</span>
        </div>
        <p className="text-sm text-muted-foreground line-clamp-2">{activity?.description}</p>
        {activity?.user && (
          <div className="flex items-center gap-2 mt-2">
            <Image 
              src={activity?.user?.avatar} 
              alt={activity?.user?.avatarAlt}
              className="w-6 h-6 rounded-full object-cover"
            />
            <span className="text-xs text-muted-foreground">{activity?.user?.name}</span>
          </div>
        )}
      </div>
    </div>
  );
};

export default RecentActivityItem;