import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import Icon from '../../../components/AppIcon';
import { cn } from '../../../utils/cn';
import { deleteReviewAsync } from '../../../store/contentSlice';
import { useToast } from '../../../contexts/ToastContext';
import ConfirmationModal from '../../../components/ui/ConfirmationModal';
import { supabaseService } from '../../../services/supabaseService';

const ReviewsManagement = () => {
    const dispatch = useDispatch();
    const { addToast } = useToast();
    const academyCourses = useSelector((state) => state.content.academy) || [];
    const vaultLessons = useSelector((state) => state.content.vault) || [];
    const [filter, setFilter] = useState('all'); // all, academy, vault, 5star, critical
    const [confirmDelete, setConfirmDelete] = useState({
        isOpen: false,
        review: null
    });
    const [allReviews, setAllReviews] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        fetchReviews();
    }, [academyCourses, vaultLessons]);

    const fetchReviews = async () => {
        setIsLoading(true);
        try {
            const rawReviews = await supabaseService.getAllCourseReviews();
            const formatted = rawReviews.map(r => {
                let title = 'Unknown Course';
                let type = 'academy';
                
                const academyMatch = academyCourses.find(c => c.id.toString() === r.course_id?.toString());
                if (academyMatch) {
                    title = academyMatch.title;
                    type = 'academy';
                } else {
                    const vaultMatch = vaultLessons.find(c => c.id.toString() === r.course_id?.toString());
                    if (vaultMatch) {
                        title = vaultMatch.title;
                        type = 'vault';
                    }
                }
                
                return {
                    id: r.id,
                    userId: r.user_id,
                    userName: r.profiles?.full_name || 'LUC Student',
                    avatar: r.profiles?.avatar_url,
                    rating: r.rating,
                    comment: r.comment,
                    date: r.created_at,
                    contentTitle: title,
                    contentType: type === 'academy' ? 'Academy Course' : 'Growth Vault',
                    contentId: r.course_id,
                    type: type
                };
            });
            setAllReviews(formatted);
        } catch (error) {
            console.error("Error fetching reviews:", error);
            addToast("Failed to fetch reviews", "error");
        } finally {
            setIsLoading(false);
        }
    };

    const handleDeleteReview = (review) => {
        setConfirmDelete({
            isOpen: true,
            review
        });
    };

    const confirmDeleteReview = () => {
        if (!confirmDelete.review) return;

        const { review } = confirmDelete;
        dispatch(deleteReviewAsync({
            id: review.id,
            courseId: review.contentId,
            date: review.date,
            userId: review.userId
        })).then((result) => {
            if (!result.error) {
                addToast("Review deleted successfully", "success");
                fetchReviews();
            } else {
                addToast("Failed to delete review", "error");
            }
            setConfirmDelete({ isOpen: false, review: null });
        });
    };

    // Filter logic
    const filteredReviews = allReviews.filter(review => {
        const rating = parseFloat(review.rating) || 0;
        if (filter === 'all') return true;
        if (filter === 'academy') return review.type === 'academy';
        if (filter === 'vault') return review.type === 'vault';
        if (filter === '5star') return Math.round(rating) === 5;
        if (filter === 'critical') return rating <= 3;
        return true;
    });

    const getFilterLabel = (key) => {
        switch (key) {
            case 'all': return 'All Reviews';
            case 'academy': return 'Academy Only';
            case 'vault': return 'Vault Only';
            case '5star': return '5 Stars';
            case 'critical': return 'Critical (1-3 Stars)';
            default: return 'All';
        }
    };

    return (
        <div className="space-y-6 p-4 md:p-6 overflow-hidden">
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                <div className="flex items-center gap-3">
                    <div className="p-3 bg-secondary/10 rounded-xl text-secondary">
                        <Icon name="MessageSquare" size={24} />
                    </div>
                    <div>
                        <h2 className="text-xl sm:text-2xl font-bold text-primary">Student Reviews</h2>
                        <p className="text-sm text-muted-foreground">Manage and analyze qualitative feedback from your community</p>
                    </div>
                </div>

                <div className="flex items-center gap-2 bg-muted/30 p-1 rounded-lg border border-border overflow-x-auto min-w-0">
                    {['all', 'academy', 'vault', '5star', 'critical'].map((key) => (
                        <button
                            key={key}
                            onClick={() => setFilter(key)}
                            className={cn(
                                "px-3 py-1.5 min-h-[44px] text-xs font-bold rounded-md transition-all whitespace-nowrap",
                                filter === key
                                    ? "bg-white text-primary shadow-sm"
                                    : "text-muted-foreground hover:text-primary hover:bg-white/50"
                            )}
                        >
                            {getFilterLabel(key)}
                        </button>
                    ))}
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="bg-card border border-border rounded-2xl p-4 md:p-6 flex items-center justify-between">
                    <div>
                        <p className="text-sm text-muted-foreground font-medium uppercase tracking-wider">Total Reviews</p>
                        <p className="text-3xl font-black text-primary mt-1">{allReviews.length}</p>
                    </div>
                    <div className="p-3 bg-primary/5 rounded-full text-primary">
                        <Icon name="MessageCircle" size={24} />
                    </div>
                </div>
                <div className="bg-card border border-border rounded-2xl p-4 md:p-6 flex items-center justify-between">
                    <div>
                        <p className="text-sm text-muted-foreground font-medium uppercase tracking-wider">Avg. Rating</p>
                        <p className="text-3xl font-black text-secondary mt-1">
                            {allReviews.length > 0
                                ? (allReviews.reduce((acc, r) => acc + (parseFloat(r.rating) || 0), 0) / allReviews.length).toFixed(1)
                                : '0.0'}
                        </p>
                    </div>
                    <div className="p-3 bg-secondary/10 rounded-full text-secondary">
                        <Icon name="Star" size={24} />
                    </div>
                </div>
                <div className="bg-card border border-border rounded-2xl p-4 md:p-6 flex items-center justify-between">
                    <div>
                        <p className="text-sm text-muted-foreground font-medium uppercase tracking-wider">Response Rate</p>
                        <p className="text-3xl font-black text-green-500 mt-1">100%</p>
                    </div>
                    <div className="p-3 bg-green-500/10 rounded-full text-green-500">
                        <Icon name="CheckCircle" size={24} />
                    </div>
                </div>
            </div>

            <div className="bg-card border border-border rounded-2xl overflow-hidden shadow-sm">
                <div className="p-4 md:p-6 border-b border-border">
                    <h3 className="font-bold text-lg">Feedback Feed</h3>
                </div>
                <div className="divide-y divide-border">
                    {filteredReviews.length > 0 ? filteredReviews.map((review, idx) => (
                        <div key={idx} className="p-4 md:p-6 hover:bg-muted/5 transition-colors group">
                            <div className="flex items-start justify-between mb-4">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-full bg-gradient-to-br from-primary to-primary/80 flex items-center justify-center text-white font-bold text-sm">
                                        {review.userName.charAt(0)}
                                    </div>
                                    <div>
                                        <h4 className="font-bold text-sm text-primary">{review.userName}</h4>
                                        <div className="flex items-center gap-2 text-xs text-muted-foreground">
                                            <span>{new Date(review.date).toLocaleDateString()}</span>
                                            <span>•</span>
                                            <span className={cn(
                                                "px-1.5 py-0.5 rounded text-[10px] font-bold uppercase",
                                                review.type === 'academy' ? "bg-purple-500/10 text-purple-600" : "bg-orange-500/10 text-orange-600"
                                            )}>
                                                {review.contentType}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-center gap-1">
                                    {[1, 2, 3, 4, 5].map((star) => (
                                        <Icon
                                            key={star}
                                            name="Star"
                                            size={16}
                                            fill={star <= review.rating ? "currentColor" : "none"}
                                            className={star <= review.rating ? "text-orange-400" : "text-muted-foreground/20"}
                                        />
                                    ))}
                                </div>
                            </div>

                            <div className="pl-13 ml-13">
                                <p className="text-sm text-muted-foreground leading-relaxed italic border-l-2 border-secondary/20 pl-4 mb-3">
                                    "{review.comment || 'No written comment.'}"
                                </p>
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-2 text-xs font-medium text-primary bg-muted/30 px-2 py-1 rounded w-fit">
                                        <Icon name={review.type === 'academy' ? "GraduationCap" : "Zap"} size={12} />
                                        {review.contentTitle}
                                    </div>

                                    {/* Admin Actions */}
                                    <div className="opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity flex gap-4">
                                        <button
                                            className="text-xs text-secondary font-bold hover:underline min-h-[44px] min-w-[44px] flex items-center justify-center"
                                            onClick={() => addToast("Reply feature coming soon", "info")}
                                        >
                                            Reply
                                        </button>
                                        <button
                                            onClick={() => handleDeleteReview(review)}
                                            className="text-xs text-red-500 font-bold hover:underline min-h-[44px] min-w-[44px] flex items-center gap-1"
                                        >
                                            <Icon name="Trash2" size={12} />
                                            Delete Review
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    )) : (
                        <div className="py-20 text-center">
                            <div className="w-20 h-20 bg-muted/20 rounded-full flex items-center justify-center mx-auto mb-4 text-muted-foreground/40">
                                <Icon name="MessageSquare" size={40} />
                            </div>
                            <h3 className="text-lg font-bold text-primary mb-1">No reviews found</h3>
                            <p className="text-sm text-muted-foreground">Try adjusting your filters or wait for more student feedback.</p>
                        </div>
                    )}
                </div>
            </div>

            <ConfirmationModal
                isOpen={confirmDelete.isOpen}
                onClose={() => setConfirmDelete({ isOpen: false, review: null })}
                onConfirm={confirmDeleteReview}
                title="Delete Review"
                message={confirmDelete.review ? `Are you sure you want to delete the review by ${confirmDelete.review.userName}? This will update the course rating.` : ""}
                confirmText="Delete Review"
                type="danger"
            />
        </div>
    );
};

export default ReviewsManagement;
