import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import ConfirmationModal from '../../../components/ui/ConfirmationModal';
import { useToast } from '../../../contexts/ToastContext';

const PartnershipManagement = () => {
    const { addToast } = useToast();
    const [requests, setRequests] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedRequest, setSelectedRequest] = useState(null);
    const [isDeleting, setIsDeleting] = useState(false);
    const [deleteId, setDeleteId] = useState(null);

    useEffect(() => {
        fetchRequests();
    }, []);

    const fetchRequests = async () => {
        setIsLoading(true);
        try {
            const data = await supabaseService.getPartnershipRequests();
            setRequests(data || []);
        } catch (error) {
            console.error('Error fetching partnership requests:', error);
            addToast('Failed to fetch requests', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleUpdateStatus = async (id, status) => {
        try {
            await supabaseService.updatePartnershipStatus(id, status);
            setRequests(prev => prev.map(r => r.id === id ? { ...r, status } : r));
            if (selectedRequest?.id === id) {
                setSelectedRequest({ ...selectedRequest, status });
            }
            addToast(`Status updated to ${status}`, 'success');
        } catch (error) {
            console.error('Error updating status:', error);
            addToast('Failed to update status', 'error');
        }
    };

    const handleDeleteClick = (id) => {
        setDeleteId(id);
    };

    const performDelete = async () => {
        if (!deleteId) return;
        setIsDeleting(true);
        try {
            await supabaseService.deletePartnershipRequest(deleteId);
            setRequests(prev => prev.filter(r => r.id !== deleteId));
            if (selectedRequest?.id === deleteId) setSelectedRequest(null);
            addToast('Request deleted successfully.', 'success');
        } catch (error) {
            console.error('Error deleting request:', error);
            addToast('Failed to delete request', 'error');
        } finally {
            setIsDeleting(false);
            setDeleteId(null);
        }
    };

    const formatDate = (dateString) => {
        if (!dateString) return '';
        return new Date(dateString).toLocaleDateString('en-US', {
            month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit'
        });
    };

    const getStatusColor = (status) => {
        switch (status) {
            case 'pending': return 'bg-yellow-500/20 text-yellow-500 border border-yellow-500/30';
            case 'reviewed': return 'bg-blue-500/20 text-blue-500 border border-blue-500/30';
            case 'accepted': return 'bg-emerald-500/20 text-emerald-500 border border-emerald-500/30';
            case 'rejected': return 'bg-rose-500/20 text-rose-500 border border-rose-500/30';
            default: return 'bg-slate-500/20 text-slate-500 border border-slate-500/30';
        }
    };

    return (
        <div className="flex flex-col lg:grid lg:grid-cols-3 gap-6 h-[calc(100vh-200px)] min-h-[600px] lg:min-h-0">
            {/* Sidebar / List */}
            <div className={`lg:col-span-1 bg-card rounded-2xl border border-border overflow-hidden flex flex-col shadow-sm ${selectedRequest ? 'hidden lg:flex' : 'flex'}`}>
                <div className="p-4 border-b border-border bg-muted/50 flex justify-between items-center">
                    <h3 className="font-bold flex items-center gap-2 text-primary">
                        <Icon name="Handshake" size={18} className="text-brand-blue" />
                        Partnership Requests
                        <span className="text-[10px] bg-brand-blue text-white px-1.5 py-0.5 rounded-full ml-1">
                            {requests.filter(r => r.status === 'pending').length}
                        </span>
                    </h3>
                    <button
                        onClick={fetchRequests}
                        className="p-2 hover:bg-muted rounded-lg transition-colors text-muted-foreground hover:text-primary"
                    >
                        <Icon name="RefreshCw" size={18} className={isLoading ? 'animate-spin' : ''} />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto scrollbar-hide">
                    {requests.length === 0 && !isLoading ? (
                        <div className="p-12 text-center text-muted-foreground">
                            <Icon name="Inbox" size={48} className="mx-auto mb-4 opacity-10" />
                            <p className="text-sm font-medium">No partnership requests</p>
                        </div>
                    ) : (
                        requests.map((request) => (
                            <div
                                key={request.id}
                                onClick={() => setSelectedRequest(request)}
                                className={`p-4 border-b border-border/50 cursor-pointer transition-all hover:bg-muted/50 relative group ${selectedRequest?.id === request.id ? 'bg-primary/5 active-message' : ''
                                    }`}
                            >
                                {selectedRequest?.id === request.id && (
                                    <div className="absolute left-0 top-0 bottom-0 w-1 bg-primary" />
                                )}
                                <div className="flex justify-between items-start mb-1 gap-2">
                                    <span className={`text-sm font-bold truncate ${request.status === 'pending' ? 'text-primary' : 'text-muted-foreground'}`}>
                                        {request.organization_name}
                                    </span>
                                    <span className="text-[10px] text-muted-foreground whitespace-nowrap shrink-0">
                                        {formatDate(request.created_at)}
                                    </span>
                                </div>
                                <div className="text-[10px] text-brand-blue font-bold uppercase tracking-wider mb-1">
                                    {request.partnership_type}
                                </div>
                                <div className={`text-xs truncate ${request.status === 'pending' ? 'text-foreground font-medium' : 'text-muted-foreground'}`}>
                                    {request.contact_person}
                                </div>
                                {request.status === 'pending' && (
                                    <div className="absolute right-4 top-1/2 -translate-y-1/2 w-2 h-2 bg-yellow-500 rounded-full" />
                                )}
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Content / Detail */}
            <div className={`lg:col-span-2 bg-card rounded-2xl border border-border overflow-hidden flex flex-col shadow-sm ${selectedRequest ? 'flex' : 'hidden lg:flex'}`}>
                {selectedRequest ? (
                    <div className="flex flex-col h-full bg-card">
                        {/* Header */}
                        <div className="p-6 border-b border-border">
                            <button
                                onClick={() => setSelectedRequest(null)}
                                className="flex items-center gap-1 text-brand-blue font-medium text-sm mb-4 lg:hidden"
                            >
                                <Icon name="ArrowLeft" size={16} />
                                Back to List
                            </button>

                            <div className="flex flex-col md:flex-row justify-between items-start gap-4">
                                <div className="space-y-3 flex-1 min-w-0">
                                    <div className="flex items-center gap-3">
                                        <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-widest ${getStatusColor(selectedRequest.status)}`}>
                                            {selectedRequest.status}
                                        </span>
                                        <span className="text-xs text-muted-foreground font-medium">
                                            {formatDate(selectedRequest.created_at)}
                                        </span>
                                    </div>
                                    <h3 className="text-2xl font-bold text-primary leading-tight break-words">
                                        {selectedRequest.organization_name}
                                    </h3>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-1">
                                        <div className="flex gap-2 items-center">
                                            <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-xs uppercase">
                                                {selectedRequest.contact_person?.[0]}
                                            </div>
                                            <div className="flex flex-col">
                                                <span className="text-sm font-bold text-primary">{selectedRequest.contact_person}</span>
                                                <span className="text-xs text-muted-foreground">{selectedRequest.email}</span>
                                            </div>
                                        </div>
                                        <div className="flex flex-col text-xs text-muted-foreground">
                                            <span>Phone: {selectedRequest.phone || 'N/A'}</span>
                                            <span>Website: {selectedRequest.website || 'N/A'}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Proposal Body */}
                        <div className="flex-1 overflow-y-auto p-6 bg-muted/20">
                            <h4 className="text-sm font-bold text-primary mb-3 uppercase tracking-wider">Partnership Proposal</h4>
                            <div className="bg-card rounded-2xl p-6 shadow-sm text-foreground whitespace-pre-wrap leading-relaxed border border-border text-sm md:text-base">
                                {selectedRequest.message}
                            </div>
                        </div>

                        {/* Footer Actions */}
                        <div className="p-4 md:p-6 border-t border-border bg-card flex flex-wrap gap-3">
                            <Button
                                variant="default"
                                size="sm"
                                iconName="Reply"
                                onClick={() => window.open(`mailto:${selectedRequest.email}?subject=Partnership Inquiry: ${selectedRequest.organization_name}`)}
                            >
                                Reply via Email
                            </Button>

                            {selectedRequest.status === 'pending' && (
                                <Button
                                    variant="outline"
                                    size="sm"
                                    iconName="Eye"
                                    onClick={() => handleUpdateStatus(selectedRequest.id, 'reviewed')}
                                >
                                    Mark Reviewed
                                </Button>
                            )}

                            {selectedRequest.status !== 'accepted' && (
                                <Button
                                    variant="outline"
                                    size="sm"
                                    iconName="CheckCircle"
                                    onClick={() => handleUpdateStatus(selectedRequest.id, 'accepted')}
                                >
                                    Accept
                                </Button>
                            )}

                            {selectedRequest.status !== 'rejected' && (
                                <Button
                                    variant="outline"
                                    size="sm"
                                    iconName="XCircle"
                                    className="text-rose-500 hover:bg-rose-50 border-rose-100"
                                    onClick={() => handleUpdateStatus(selectedRequest.id, 'rejected')}
                                >
                                    Reject
                                </Button>
                            )}

                            <div className="flex-1" />

                            <Button
                                variant="outline"
                                size="sm"
                                className="text-destructive hover:bg-destructive/10 hover:text-destructive border-transparent"
                                iconName="Trash2"
                                onClick={() => handleDeleteClick(selectedRequest.id)}
                            >
                                Delete
                            </Button>
                        </div>
                    </div>
                ) : (
                    <div className="flex-1 flex flex-col items-center justify-center p-12 text-center text-muted-foreground">
                        <div className="w-20 h-20 rounded-full bg-muted flex items-center justify-center mb-6">
                            <Icon name="Handshake" size={40} className="opacity-20 text-primary" />
                        </div>
                        <h4 className="text-lg font-bold text-primary mb-2">Partnership Hub</h4>
                        <p className="max-w-xs text-sm">Select a partnership proposal from the list to review organization details and collaborate.</p>
                    </div>
                )}
            </div>

            <ConfirmationModal
                isOpen={!!deleteId}
                onClose={() => setDeleteId(null)}
                onConfirm={performDelete}
                title="Delete Request"
                message="Are you sure you want to permanently delete this partnership request? This action cannot be undone."
                type="danger"
                isLoading={isDeleting}
                confirmText="Delete Request"
            />
        </div>
    );
};

export default PartnershipManagement;
