import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { 
    updateHeroAsync, 
    updateStatsAsync, 
    updateCTAAsync, 
    updateSpotlightAsync, 
    updateAcademySampleAsync,
    updateStoriesAsync 
} from '../../../store/contentSlice';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import { useToast } from '../../../contexts/ToastContext';

const ContentManagement = () => {
    const dispatch = useDispatch();
    const { addToast } = useToast();
    const hero = useSelector((state) => state.content.hero);
    const stats = useSelector((state) => state.content.stats);
    const cta = useSelector((state) => state.content.cta);
    const spotlight = useSelector((state) => state.content.spotlight);
    const academy = useSelector((state) => state.content.academy) || [];
    const vault = useSelector((state) => state.content.vault) || [];
    const academySample = useSelector((state) => state.content.academySample);
    const successStories = useSelector((state) => state.content.successStories) || [];

    const [heroForm, setHeroForm] = useState(hero);
    const [statsForm, setStatsForm] = useState(stats);
    const [storiesForm, setStoriesForm] = useState(successStories);
    const [spotlightForm, setSpotlightForm] = useState(spotlight || {
        type: 'course',
        id: '1',
        badgeText: 'Academy Spotlight',
        label: 'Skill of the Week'
    });
    const [sampleForm, setSampleForm] = useState(academySample || {
        courseId: '',
        title: '',
        description: '',
        badgeText: 'Featured Lesson Today',
        videoId: ''
    });

    useEffect(() => {
        if (successStories.length > 0 && storiesForm.length === 0) {
            setStoriesForm(successStories);
        }
    }, [successStories]);

    const defaults = {
        whatsapp: {
            title: "Join Our WhatsApp Community",
            description: "Get instant notifications...",
            buttonText: "Join WhatsApp Channel",
            link: "https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V"
        },
        discovery: {
            title: "Start Your Discovery Journey",
            description: "Explore 2,500+ verified opportunities...",
            buttonText: "Explore Opportunities"
        },
        partner: {
            title: "Organizations & Institutions",
            description: "Reach 50,000+ ambitious students..."
        }
    };

    const [ctaForm, setCtaForm] = useState(cta || defaults);


    const handleHeroSubmit = (e) => {
        e.preventDefault();
        dispatch(updateHeroAsync(heroForm));
        addToast('Hero section updated on Supabase!', 'success');
    };

    const handleSpotlightSubmit = (e) => {
        e.preventDefault();
        dispatch(updateSpotlightAsync(spotlightForm));
        addToast('Academy Spotlight updated successfully!', 'success');
    };

    const handleSampleSubmit = (e) => {
        e.preventDefault();
        dispatch(updateAcademySampleAsync(sampleForm));
        addToast('Academy Sample Lesson updated successfully!', 'success');
    };

    const handleStatChange = (index, field, value) => {
        const newStats = [...statsForm];
        newStats[index] = { ...newStats[index], [field]: value };
        setStatsForm(newStats);
    };

    const handleStatsSubmit = (e) => {
        e.preventDefault();
        dispatch(updateStatsAsync(statsForm));
        addToast('Stats updated on Supabase!', 'success');
    };

    const handleCtaChange = (section, field, value) => {
        setCtaForm({
            ...ctaForm,
            [section]: {
                ...ctaForm[section],
                [field]: value
            }
        });
    };

    const handleCtaSubmit = (e) => {
        e.preventDefault();
        dispatch(updateCTAAsync(ctaForm));
        addToast('CTA section updated on Supabase!', 'success');
    };

    // Stories Logic
    const handleStoryChange = (index, field, value) => {
        const newStories = [...storiesForm];
        newStories[index] = { ...newStories[index], [field]: value };
        setStoriesForm(newStories);
    };

    const addStory = () => {
        setStoriesForm([
            ...storiesForm,
            { id: Date.now(), name: '', achievement: '', image: '', story: '', opportunity: '', country: 'Global', year: new Date().getFullYear() }
        ]);
    };

    const removeStory = (index) => {
        const newStories = storiesForm.filter((_, i) => i !== index);
        setStoriesForm(newStories);
    };

    const handleStoriesSubmit = (e) => {
        e.preventDefault();
        dispatch(updateStoriesAsync(storiesForm));
        addToast('Community Success Stories updated!', 'success');
    };

    return (
        <div className="p-4 md:p-6 space-y-8 pb-20 overflow-hidden">
            {/* Community Success Stories Management */}
            <section className="bg-card rounded-2xl p-4 md:p-6 shadow-sm border border-border">
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-6">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-emerald-500/10 rounded-lg text-emerald-500">
                            <Icon name="Star" size={24} />
                        </div>
                        <div>
                            <h2 className="text-xl sm:text-2xl font-bold">Community Success Stories</h2>
                            <p className="text-xs text-muted-foreground">Manage the testimonials shown on the homepage.</p>
                        </div>
                    </div>
                    <Button onClick={addStory} variant="outline" size="sm" iconName="Plus">Add Story</Button>
                </div>

                <form onSubmit={handleStoriesSubmit} className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {storiesForm.map((story, index) => (
                            <div key={story.id || index} className="p-6 bg-muted/30 border border-border rounded-2xl space-y-4 relative group">
                                <button 
                                    type="button"
                                    onClick={() => removeStory(index)}
                                    className="absolute -top-2 -right-2 w-11 h-11 bg-destructive text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity shadow-lg"
                                >
                                    <Icon name="X" size={16} />
                                </button>
                                
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1">Name</label>
                                        <input
                                            type="text"
                                            value={story.name}
                                            onChange={(e) => handleStoryChange(index, 'name', e.target.value)}
                                            className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm"
                                            placeholder="User Name"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1">Achievement</label>
                                        <input
                                            type="text"
                                            value={story.achievement}
                                            onChange={(e) => handleStoryChange(index, 'achievement', e.target.value)}
                                            className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm"
                                            placeholder="e.g. Won $5k Scholarship"
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1">Image URL</label>
                                    <input
                                        type="text"
                                        value={story.image}
                                        onChange={(e) => handleStoryChange(index, 'image', e.target.value)}
                                        className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm"
                                        placeholder="https://..."
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1">The Story</label>
                                    <textarea
                                        value={story.story}
                                        onChange={(e) => handleStoryChange(index, 'story', e.target.value)}
                                        className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm min-h-[100px]"
                                        placeholder="What happened?"
                                    />
                                </div>

                                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                                    <div>
                                        <label className="block text-[10px] font-bold uppercase tracking-wider text-muted-foreground mb-1">Opportunity</label>
                                        <input
                                            type="text"
                                            value={story.opportunity}
                                            onChange={(e) => handleStoryChange(index, 'opportunity', e.target.value)}
                                            className="w-full px-2 py-1.5 bg-background border border-border rounded text-xs"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-bold uppercase tracking-wider text-muted-foreground mb-1">Country</label>
                                        <input
                                            type="text"
                                            value={story.country}
                                            onChange={(e) => handleStoryChange(index, 'country', e.target.value)}
                                            className="w-full px-2 py-1.5 bg-background border border-border rounded text-xs"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-bold uppercase tracking-wider text-muted-foreground mb-1">Year</label>
                                        <input
                                            type="number"
                                            value={story.year}
                                            onChange={(e) => handleStoryChange(index, 'year', parseInt(e.target.value))}
                                            className="w-full px-2 py-1.5 bg-background border border-border rounded text-xs"
                                        />
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                    
                    {storiesForm.length === 0 && (
                        <div className="p-12 text-center border-2 border-dashed border-border rounded-3xl">
                            <Icon name="Star" size={48} className="mx-auto mb-4 opacity-10" />
                            <p className="text-muted-foreground">No stories added yet. Click 'Add Story' to begin.</p>
                        </div>
                    )}

                    <Button type="submit" variant="default" iconName="Save" size="lg" className="w-full md:w-auto">Save All Stories</Button>
                </form>
            </section>

            {/* Academy Sample Lesson Management */}
            <section className="bg-card rounded-2xl p-4 md:p-6 shadow-sm border border-border">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-primary/10 rounded-lg text-primary">
                        <Icon name="Play" size={24} />
                    </div>
                    <div>
                        <h2 className="text-xl sm:text-2xl font-bold">Featured Academy Sample</h2>
                        <p className="text-xs text-muted-foreground">Manage the video and text shown at the top of the Academy page.</p>
                    </div>
                </div>

                <form onSubmit={handleSampleSubmit} className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="md:col-span-2">
                            <label className="block text-sm font-medium mb-1">Select Course to Link</label>
                            <select
                                value={sampleForm.courseId}
                                onChange={(e) => setSampleForm({ ...sampleForm, courseId: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg outline-none focus:ring-2 focus:ring-primary"
                            >
                                <option value="">Auto-select (First Course)</option>
                                {academy.map(c => <option key={c.id} value={c.id}>{c.title}</option>)}
                            </select>
                            <p className="mt-1 text-[10px] text-muted-foreground italic">Linking a course takes its Video ID and Student Count automatically.</p>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Section Badge (e.g. Free Sample Lesson)</label>
                            <input
                                type="text"
                                value={sampleForm.badgeText}
                                onChange={(e) => setSampleForm({ ...sampleForm, badgeText: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg outline-none focus:ring-2 focus:ring-primary"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Headline Override (Leave blank to use course title)</label>
                            <input
                                type="text"
                                value={sampleForm.title}
                                onChange={(e) => setSampleForm({ ...sampleForm, title: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg outline-none focus:ring-2 focus:ring-primary"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">YouTube Video ID (e.g. dQw4w9WgXcQ)</label>
                            <input
                                type="text"
                                value={sampleForm.videoId}
                                onChange={(e) => setSampleForm({ ...sampleForm, videoId: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg outline-none focus:ring-2 focus:ring-primary"
                                placeholder="Paste the letters after v= in the YouTube link"
                            />
                            <p className="mt-1 text-[10px] text-muted-foreground italic">Leave blank to try pulling from the linked course.</p>
                        </div>
                        <div className="md:col-span-2">
                            <label className="block text-sm font-medium mb-1">Description Override (Leave blank to use course description)</label>
                            <textarea
                                value={sampleForm.description}
                                onChange={(e) => setSampleForm({ ...sampleForm, description: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg outline-none focus:ring-2 focus:ring-primary min-h-[80px]"
                            />
                        </div>
                    </div>

                    <Button type="submit" variant="default" iconName="Save">Save Academy Settings</Button>
                </form>
            </section>

            {/* Academy Spotlight Management */}
            <section className="bg-card rounded-2xl p-4 md:p-6 shadow-sm border border-border">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-secondary/10 rounded-lg text-secondary">
                        <Icon name="GraduationCap" size={24} />
                    </div>
                    <div>
                        <h2 className="text-xl sm:text-2xl font-bold">Academy Spotlight</h2>
                        <p className="text-xs text-muted-foreground">Feature a specific course or quick win on the homepage hero.</p>
                    </div>
                </div>

                <form onSubmit={handleSpotlightSubmit} className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium mb-1">Content Type</label>
                            <select
                                value={spotlightForm.type}
                                onChange={(e) => {
                                    const newType = e.target.value;
                                    const firstItem = newType === 'course' ? academy[0]?.id : vault[0]?.id;
                                    setSpotlightForm({ ...spotlightForm, type: newType, id: firstItem?.toString() || '' });
                                }}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg outline-none focus:ring-2 focus:ring-primary"
                            >
                                <option value="course">Academy Course</option>
                                <option value="vault">Vault Quick Win</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Select Item</label>
                            <select
                                value={spotlightForm.id}
                                onChange={(e) => setSpotlightForm({ ...spotlightForm, id: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg outline-none focus:ring-2 focus:ring-primary"
                            >
                                {spotlightForm.type === 'course' ? (
                                    academy.map(c => <option key={c.id} value={c.id}>{c.title}</option>)
                                ) : (
                                    vault.map(v => <option key={v.id} value={v.id}>{v.title}</option>)
                                )}
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Badge Text (e.g. Academy Spotlight)</label>
                            <input
                                type="text"
                                value={spotlightForm.badgeText}
                                onChange={(e) => setSpotlightForm({ ...spotlightForm, badgeText: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg outline-none focus:ring-2 focus:ring-primary"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Sub-label (e.g. Skill of the Week)</label>
                            <input
                                type="text"
                                value={spotlightForm.label}
                                onChange={(e) => setSpotlightForm({ ...spotlightForm, label: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg outline-none focus:ring-2 focus:ring-primary"
                            />
                        </div>
                    </div>

                    <div className="p-4 bg-primary/5 rounded-xl border border-dashed border-primary/20">
                        <p className="text-xs font-bold text-primary mb-2 flex items-center gap-2">
                            <Icon name="Eye" size={14} /> Preview of Selected Item
                        </p>
                        {(() => {
                            const item = spotlightForm.type === 'course'
                                ? academy.find(c => c.id.toString() === spotlightForm.id.toString())
                                : vault.find(v => v.id.toString() === spotlightForm.id.toString());
                            return item ? (
                                <div className="flex items-center gap-3">
                                    <img src={item.image || item.thumbnail} className="w-16 h-10 object-cover rounded shadow" alt="" />
                                    <div>
                                        <p className="text-sm font-bold truncate max-w-[200px]">{item.title}</p>
                                        <p className="text-[10px] text-muted-foreground uppercase">{spotlightForm.type} • {item.duration}</p>
                                    </div>
                                </div>
                            ) : null;
                        })()}
                    </div>

                    <Button type="submit" variant="default" iconName="Save">Update Spotlight Content</Button>
                </form>
            </section>

            {/* Hero Section Management */}
            <section className="bg-card rounded-2xl p-4 md:p-6 shadow-sm border border-border">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-primary/10 rounded-lg text-primary">
                        <Icon name="Layout" size={24} />
                    </div>
                    <h2 className="text-xl sm:text-2xl font-bold">Manage Hero Section</h2>
                </div>

                <form onSubmit={handleHeroSubmit} className="space-y-4">
                    <div className="grid grid-cols-1 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">Headline</label>
                            <input
                                type="text"
                                value={heroForm?.title}
                                onChange={(e) => setHeroForm({ ...heroForm, title: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Subheadline</label>
                            <textarea
                                value={heroForm?.subtitle}
                                onChange={(e) => setHeroForm({ ...heroForm, subtitle: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none min-h-[100px]"
                            />
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium mb-1">Primary CTA Button Text</label>
                                <input
                                    type="text"
                                    value={heroForm?.primaryCTA || ''}
                                    onChange={(e) => setHeroForm({ ...heroForm, primaryCTA: e.target.value })}
                                    className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium mb-1">Secondary CTA Button Text</label>
                                <input
                                    type="text"
                                    value={heroForm?.secondaryCTA || ''}
                                    onChange={(e) => setHeroForm({ ...heroForm, secondaryCTA: e.target.value })}
                                    className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                                />
                            </div>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">WhatsApp Community Link</label>
                            <input
                                type="text"
                                value={heroForm?.secondaryLink || ''}
                                onChange={(e) => setHeroForm({ ...heroForm, secondaryLink: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                            />
                        </div>
                    </div>
                    <Button type="submit" variant="default">Save Hero Changes</Button>
                </form>
            </section>

            {/* Community Stats Management */}
            <section className="bg-card rounded-2xl p-4 md:p-6 shadow-sm border border-border">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-accent/10 rounded-lg text-accent">
                        <Icon name="BarChart" size={24} />
                    </div>
                    <h2 className="text-xl sm:text-2xl font-bold">Manage Community Stats</h2>
                </div>

                <form onSubmit={handleStatsSubmit} className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                        {statsForm?.map((stat, index) => (
                            <div key={index} className="p-4 bg-muted rounded-xl border border-border space-y-3">
                                <div className="text-sm font-bold text-primary">Stat #{index + 1}</div>
                                <div>
                                    <label className="block text-xs font-medium mb-1">Label</label>
                                    <input
                                        type="text"
                                        value={stat?.label}
                                        onChange={(e) => handleStatChange(index, 'label', e.target.value)}
                                        className="w-full px-3 py-1 bg-background border border-border rounded-md text-sm"
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-medium mb-1">Value</label>
                                    <input
                                        type="text"
                                        value={stat?.value}
                                        onChange={(e) => handleStatChange(index, 'value', e.target.value)}
                                        className="w-full px-3 py-1 bg-background border border-border rounded-md text-sm"
                                    />
                                </div>
                            </div>
                        ))}
                    </div>
                    <Button type="submit" variant="default">Update Stats</Button>
                </form>
            </section>

            {/* CTA Section Management */}
            <section className="bg-card rounded-2xl p-4 md:p-6 shadow-sm border border-border">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-brand-blue/10 rounded-lg text-brand-blue">
                        <Icon name="MessageCircle" size={24} />
                    </div>
                    <h2 className="text-xl sm:text-2xl font-bold">Manage CTA Sections</h2>
                </div>

                <form onSubmit={handleCtaSubmit} className="space-y-8">
                    {/* WhatsApp Section */}
                    <div className="space-y-4">
                        <h3 className="font-semibold text-lg">WhatsApp Community</h3>
                        <div>
                            <label className="block text-sm font-medium mb-1">Title</label>
                            <input
                                type="text"
                                value={ctaForm.whatsapp?.title || ''}
                                onChange={(e) => handleCtaChange('whatsapp', 'title', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Description</label>
                            <textarea
                                value={ctaForm.whatsapp?.description || ''}
                                onChange={(e) => handleCtaChange('whatsapp', 'description', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg min-h-[80px]"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Button Text</label>
                            <input
                                type="text"
                                value={ctaForm.whatsapp?.buttonText || ''}
                                onChange={(e) => handleCtaChange('whatsapp', 'buttonText', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Community Link (URL)</label>
                            <input
                                type="text"
                                value={ctaForm.whatsapp?.link || ''}
                                onChange={(e) => handleCtaChange('whatsapp', 'link', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                                placeholder="https://whatsapp.com/channel/..."
                            />
                        </div>
                    </div>

                    <div className="h-px bg-border my-6"></div>

                    {/* Discovery Section */}
                    <div className="space-y-4">
                        <h3 className="font-semibold text-lg">Discovery Section</h3>
                        <div>
                            <label className="block text-sm font-medium mb-1">Title</label>
                            <input
                                type="text"
                                value={ctaForm.discovery?.title || ''}
                                onChange={(e) => handleCtaChange('discovery', 'title', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Description</label>
                            <textarea
                                value={ctaForm.discovery?.description || ''}
                                onChange={(e) => handleCtaChange('discovery', 'description', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg min-h-[80px]"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Button Text</label>
                            <input
                                type="text"
                                value={ctaForm.discovery?.buttonText || ''}
                                onChange={(e) => handleCtaChange('discovery', 'buttonText', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                            />
                        </div>
                    </div>

                    <div className="h-px bg-border my-6"></div>

                    {/* Partner Section */}
                    <div className="space-y-4">
                        <h3 className="font-semibold text-lg">Partner Section</h3>
                        <div>
                            <label className="block text-sm font-medium mb-1">Title</label>
                            <input
                                type="text"
                                value={ctaForm.partner?.title || ''}
                                onChange={(e) => handleCtaChange('partner', 'title', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Description</label>
                            <textarea
                                value={ctaForm.partner?.description || ''}
                                onChange={(e) => handleCtaChange('partner', 'description', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg min-h-[80px]"
                            />
                        </div>
                    </div>

                    <Button type="submit" variant="default">Update CTA Sections</Button>
                </form>
            </section>
        </div>
    );
};

export default ContentManagement;
