import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { supabaseService } from '../../../services/supabaseService';
import { updateOpportunityAsync } from '../../../store/contentSlice';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import ConfirmationModal from '../../../components/ui/ConfirmationModal';
import { useToast } from '../../../contexts/ToastContext';

const MessageManagement = () => {
    const dispatch = useDispatch();
    const { addToast } = useToast();
    const opportunities = useSelector((state) => state.content.allOpportunities);
    const [messages, setMessages] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedMessage, setSelectedMessage] = useState(null);
    const [isDeleting, setIsDeleting] = useState(false);
    const [deleteId, setDeleteId] = useState(null);

    useEffect(() => {
        fetchMessages();
    }, []);

    const fetchMessages = async () => {
        setIsLoading(true);
        try {
            const data = await supabaseService.getContactMessages();
            setMessages(data || []);
        } catch (error) {
            console.error('Error fetching messages:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleUpdateStatus = async (id, status, silent = false) => {
        try {
            const updated = await supabaseService.updateMessageStatus(id, status);

            if (!updated) {
                throw new Error("Update failed: No rows affected. Check your Supabase RLS policies.");
            }

            setMessages(prev => prev.map(m => m.id === id ? { ...m, status } : m));
            if (selectedMessage?.id === id) {
                setSelectedMessage({ ...selectedMessage, status });
            }
            if (!silent) addToast(`Status updated to ${status}`, 'success');
        } catch (error) {
            console.error('Error updating status:', error);
            addToast('Failed to update status. Check Supabase policies.', 'error');
        }
    };

    const handleDeleteClick = (id) => {
        setDeleteId(id);
    };

    const handlePublishStory = async (message) => {
        // Parse rating and story from message text
        const ratingMatch = message.message.match(/Rating: (\d)\/5/);
        const storyParts = message.message.split('Story:\n');
        const rating = ratingMatch ? parseInt(ratingMatch[1]) : 5;
        const storyText = storyParts.length > 1 ? storyParts[1].trim() : message.message;

        // Find opportunity by title in subject
        const oppTitle = message.subject.replace('Success Story: ', '');
        const opp = opportunities.find(o => o.title === oppTitle);

        if (!opp) {
            addToast("Could not find matching opportunity for this story.", "error");
            return;
        }

        try {
            const updatedStories = [...(opp.successStories || []), {
                name: message.name,
                rating,
                story: storyText,
                date: new Date().toISOString()
            }];

            await dispatch(updateOpportunityAsync({
                ...opp,
                successStories: updatedStories
            })).unwrap();

            await handleUpdateStatus(message.id, 'replied', true);
            addToast("Success story published and visible to users!", "success");
        } catch (error) {
            console.error("Failed to publish story:", error);
            addToast("Failed to publish story", "error");
        }
    };

    const performDelete = async () => {
        if (!deleteId) return;
        setIsDeleting(true);
        try {
            await supabaseService.deleteContactMessage(deleteId);
            setMessages(prev => prev.filter(m => m.id !== deleteId));
            if (selectedMessage?.id === deleteId) setSelectedMessage(null);
            addToast('Message deleted successfully.', 'success');
        } catch (error) {
            console.error('Error deleting message:', error);
            addToast('Failed to delete message. Check Supabase policies.', 'error');
        } finally {
            setIsDeleting(false);
            setDeleteId(null);
        }
    };

    const formatDate = (dateString) => {
        if (!dateString) return '';
        return new Date(dateString).toLocaleDateString('en-US', {
            month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit'
        });
    };

    const getStatusColor = (status) => {
        switch (status) {
            case 'unread': return 'bg-blue-500/20 text-blue-500 border border-blue-500/30';
            case 'read': return 'bg-slate-500/20 text-slate-500 border border-slate-500/30';
            case 'replied': return 'bg-emerald-500/20 text-emerald-500 border border-emerald-500/30';
            default: return 'bg-slate-500/20 text-slate-500 border border-slate-500/30';
        }
    };

    return (
        <div className="flex flex-col lg:grid lg:grid-cols-3 gap-6 h-[calc(100vh-200px)] min-h-[600px] lg:min-h-0">
            {/* Sidebar / List */}
            <div className={`lg:col-span-1 bg-card rounded-2xl border border-border overflow-hidden flex flex-col shadow-sm ${selectedMessage ? 'hidden lg:flex' : 'flex'}`}>
                <div className="p-4 border-b border-border bg-muted/50 flex justify-between items-center">
                    <h3 className="font-bold flex items-center gap-2 text-primary">
                        <Icon name="Mail" size={18} className="text-brand-blue" />
                        Inbox
                        <span className="text-[10px] bg-brand-blue text-white px-1.5 py-0.5 rounded-full ml-1">
                            {messages.filter(m => m.status === 'unread').length}
                        </span>
                    </h3>
                    <button
                        onClick={fetchMessages}
                        className="p-2 hover:bg-muted rounded-lg transition-colors text-muted-foreground hover:text-primary"
                    >
                        <Icon name="RefreshCw" size={18} className={isLoading ? 'animate-spin' : ''} />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto scrollbar-hide">
                    {messages.length === 0 && !isLoading ? (
                        <div className="p-12 text-center text-muted-foreground">
                            <Icon name="Inbox" size={48} className="mx-auto mb-4 opacity-10" />
                            <p className="text-sm font-medium">Your inbox is empty</p>
                        </div>
                    ) : (
                        messages.map((message) => (
                            <div
                                key={message.id}
                                onClick={() => setSelectedMessage(message)}
                                className={`p-4 border-b border-border/50 cursor-pointer transition-all hover:bg-muted/50 relative group ${selectedMessage?.id === message.id ? 'bg-primary/5 active-message' : ''
                                    }`}
                            >
                                {selectedMessage?.id === message.id && (
                                    <div className="absolute left-0 top-0 bottom-0 w-1 bg-primary" />
                                )}
                                <div className="flex justify-between items-start mb-1 gap-2">
                                    <span className={`text-sm font-bold truncate ${message.status === 'unread' ? 'text-primary' : 'text-muted-foreground'}`}>
                                        {message.name}
                                    </span>
                                    <span className="text-[10px] text-muted-foreground whitespace-nowrap shrink-0">
                                        {formatDate(message.created_at)}
                                    </span>
                                </div>
                                <div className="text-[10px] text-brand-blue font-bold uppercase tracking-wider mb-1">
                                    {message.inquiry_type?.replace('_', ' ')}
                                </div>
                                <div className={`text-xs truncate ${message.status === 'unread' ? 'text-foreground font-medium' : 'text-muted-foreground'}`}>
                                    {message.subject}
                                </div>
                                {message.status === 'unread' && (
                                    <div className="absolute right-4 top-1/2 -translate-y-1/2 w-2 h-2 bg-blue-500 rounded-full" />
                                )}
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Content / Detail */}
            <div className={`lg:col-span-2 bg-card rounded-2xl border border-border overflow-hidden flex flex-col shadow-sm ${selectedMessage ? 'flex' : 'hidden lg:flex'}`}>
                {selectedMessage ? (
                    <div className="flex flex-col h-full bg-card">
                        {/* Header */}
                        <div className="p-6 border-b border-border">
                            <button
                                onClick={() => setSelectedMessage(null)}
                                className="flex items-center gap-1 text-brand-blue font-medium text-sm mb-4 lg:hidden"
                            >
                                <Icon name="ArrowLeft" size={16} />
                                Back to Inbox
                            </button>

                            <div className="flex flex-col md:flex-row justify-between items-start gap-4">
                                <div className="space-y-3 flex-1 min-w-0">
                                    <div className="flex items-center gap-3">
                                        <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-widest ${getStatusColor(selectedMessage.status)}`}>
                                            {selectedMessage.status}
                                        </span>
                                        <span className="text-xs text-muted-foreground font-medium">
                                            {formatDate(selectedMessage.created_at)}
                                        </span>
                                    </div>
                                    <h3 className="text-2xl font-bold text-primary leading-tight break-words">
                                        {selectedMessage.subject}
                                    </h3>
                                    <div className="flex flex-wrap items-center gap-4 pt-1">
                                        <div className="flex gap-2 items-center">
                                            <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-xs uppercase">
                                                {selectedMessage.name?.[0]}
                                            </div>
                                            <div className="flex flex-col">
                                                <span className="text-sm font-bold text-primary">{selectedMessage.name}</span>
                                                <span className="text-xs text-muted-foreground">{selectedMessage.email}</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Message Body */}
                        <div className="flex-1 overflow-y-auto p-6 bg-muted/20">
                            <div className="bg-card rounded-2xl p-6 shadow-sm text-foreground whitespace-pre-wrap leading-relaxed border border-border text-sm md:text-base">
                                {selectedMessage.message}
                            </div>
                        </div>

                        {/* Footer Actions */}
                        <div className="p-4 md:p-6 border-t border-border bg-card flex flex-wrap gap-3">
                            <Button
                                variant="default"
                                size="sm"
                                iconName="Reply"
                                onClick={() => window.open(`mailto:${selectedMessage.email}?subject=Re: ${selectedMessage.subject}`)}
                            >
                                Reply
                            </Button>

                            {selectedMessage.status === 'unread' && (
                                <Button
                                    variant="outline"
                                    size="sm"
                                    iconName="CheckCheck"
                                    onClick={() => handleUpdateStatus(selectedMessage.id, 'read')}
                                >
                                    Mark Read
                                </Button>
                            )}

                            {selectedMessage.status !== 'replied' && (
                                <Button
                                    variant="outline"
                                    size="sm"
                                    iconName="MessageSquareCheck"
                                    onClick={() => handleUpdateStatus(selectedMessage.id, 'replied')}
                                >
                                    Mark Replied
                                </Button>
                            )}

                            {selectedMessage.inquiry_type === 'success_story' && selectedMessage.status !== 'replied' && (
                                <Button
                                    variant="secondary"
                                    size="sm"
                                    iconName="Trophy"
                                    onClick={() => handlePublishStory(selectedMessage)}
                                >
                                    Publish Story
                                </Button>
                            )}

                            <div className="flex-1" />

                            <Button
                                variant="outline"
                                size="sm"
                                className="text-destructive hover:bg-destructive/10 hover:text-destructive border-transparent"
                                iconName="Trash2"
                                onClick={() => handleDeleteClick(selectedMessage.id)}
                            >
                                Delete
                            </Button>
                        </div>
                    </div>
                ) : (
                    <div className="flex-1 flex flex-col items-center justify-center p-12 text-center text-muted-foreground">
                        <div className="w-20 h-20 rounded-full bg-muted flex items-center justify-center mb-6">
                            <Icon name="Mail" size={40} className="opacity-20 text-primary" />
                        </div>
                        <h4 className="text-lg font-bold text-primary mb-2">Private Inbox</h4>
                        <p className="max-w-xs text-sm">Select any message from the list on the left to read its content and respond.</p>
                    </div>
                )}
            </div>

            <ConfirmationModal
                isOpen={!!deleteId}
                onClose={() => setDeleteId(null)}
                onConfirm={performDelete}
                title="Delete Message"
                message="Are you sure you want to permanently delete this message? This action cannot be undone."
                type="danger"
                isLoading={isDeleting}
                confirmText="Delete Message"
            />
        </div>
    );
};

export default MessageManagement;
