const AdminDashboard = () => {
  const dispatch = useDispatch();
  const location = useLocation();
  const { addToast } = useToast();
  const { user, roles } = useSelector((state) => state.auth);
  const [activeTab, setActiveTab] = useState('overview');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [mfaVerified, setMfaVerified] = useState(true);
  const [checkingMfa, setCheckingMfa] = useState(true);
  const [editingOpportunity, setEditingOpportunity] = useState(null);
  const opportunities = useSelector((state) => state.content.allOpportunities);
  const [users, setUsers] = useState([]);
  const [isLoadingUsers, setIsLoadingUsers] = useState(false);
  const [savedItemsCount, setSavedItemsCount] = useState(0);
  const [opportunityGrowth, setOpportunityGrowth] = useState('0%');
  const [userGrowth, setUserGrowth] = useState('0%');
  const [savedGrowth, setSavedGrowth] = useState('0%');
  const [pendingPartnerships, setPendingPartnerships] = useState(0);
  const [pendingSubmissions, setPendingSubmissions] = useState(0);
  const [unreadMessages, setUnreadMessages] = useState(0);
  const [pendingDrafts, setPendingDrafts] = useState(0);

  useEffect(() => {
    if (location.state?.activeTab) {
      setActiveTab(location.state.activeTab);
    }
  }, [location.state]);

  // Confirmation Modal State
  const [confirmConfig, setConfirmConfig] = useState({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => { },
    type: 'danger'
  });

  // Real-time Notification Listener
  useEffect(() => {
    const channel = supabaseService.supabase.channel('admin_notifications');
    
    console.log("Admin Dashboard subscribing to admin_notifications...");

    channel.on('broadcast', { event: 'COURSE_SUBMITTED' }, ({ payload }) => {
      console.log("Received COURSE_SUBMITTED broadcast:", payload);
      addToast(`New Course: "${payload.title}" submitted by ${payload.instructor_name}`, 'success');
      setPendingDrafts(prev => prev + 1);
    });

    channel.on('broadcast', { event: 'NEW_OPPORTUNITY_SUBMISSION' }, ({ payload }) => {
      console.log("Received NEW_OPPORTUNITY_SUBMISSION broadcast:", payload);
      setPendingSubmissions(prev => prev + 1);
      addToast(`New opportunity: "${payload.title}" submitted by ${payload.submitter_name}`, 'info');
    });

    channel.on('broadcast', { event: 'WAITLIST_JOINED' }, ({ payload }) => {
      console.log("Received WAITLIST_JOINED broadcast:", payload);
      addToast(`Gear Waitlist: ${payload.studentName} just joined the Founders Gear list!`, 'success');
      setPendingSubmissions(prev => prev + 1);
    });

    channel.on('broadcast', { event: 'PAYMENT_PENDING' }, ({ payload }) => {
      console.log("Received PAYMENT_PENDING broadcast:", payload);
      addToast(`💰 New Payment: ${payload.userName} paid ₦${payload.amount?.toLocaleString()} for ${payload.courseTitle}`, 'success');
    });

    // Real-time listener for contact messages (New & Status Updates)
    channel.on('postgres_changes', { 
      event: '*', 
      schema: 'public', 
      table: 'contact_messages' 
    }, (payload) => {
      if (payload.eventType === 'INSERT') {
        setUnreadMessages(prev => prev + 1);
        addToast(`New Message: ${payload.new.name} sent a message`, 'info');
      } else if (payload.eventType === 'UPDATE') {
        // If a message was marked as read or replied, decrement the unread count
        if (payload.old?.status === 'unread' && (payload.new.status === 'read' || payload.new.status === 'replied')) {
          setUnreadMessages(prev => Math.max(0, prev - 1));
        }
      } else if (payload.eventType === 'DELETE') {
        if (payload.old?.status === 'unread') {
          setUnreadMessages(prev => Math.max(0, prev - 1));
        }
      }
    });

    channel.subscribe((status) => {
      console.log("Admin Dashboard notification channel status:", status);
    });

    return () => {
      console.log("Admin Dashboard unsubscribing from admin_notifications");
      channel.unsubscribe();
    };
  }, []);

  useEffect(() => {
    const initDashboard = async () => {
      if (!user?.id) return;
      await fetchUsers();
      try {
        // 1. Check MFA Status for high-privilege roles
        const mfaData = await supabaseService.getMfaFactors();
        const activeFactors = mfaData.totp?.filter(f => f.status === 'verified') || [];
        setMfaVerified(activeFactors.length > 0);

        // 2. Refresh Profile Data
        const profile = await supabaseService.getProfile(user.id);
        if (profile) {
            dispatch(updateUserDetails({ gender: profile.gender }));
        }

        const savedItems = await supabaseService.getAllSavedOpportunities();
        setSavedItemsCount(savedItems.length);
        setSavedGrowth(calculateGrowth(savedItems));

        // Fetch pending counts
        const partnerships = await supabaseService.getPartnershipRequests();
        setPendingPartnerships(partnerships.filter(p => p.status === 'pending').length);

        const submissions = await supabaseService.getOpportunitySubmissions();
        setPendingSubmissions(submissions.filter(s => s.status === 'pending').length);

        const messages = await supabaseService.getContactMessages();
        setUnreadMessages(messages.filter(m => m.status === 'unread').length);

        const drafts = await supabaseService.getPendingCourseDrafts();
        setPendingDrafts(drafts.length);
      } catch (error) {
        console.error("Error fetching dashboard data:", error);
        if (error.message?.includes('MFA')) setMfaVerified(false);
      } finally {
        setCheckingMfa(false);
      }
    };
    initDashboard();
  }, [user?.id, dispatch]);

  const calculateGrowth = (items, dateField = 'created_at') => {
    const now = new Date();
    const thirtyDaysAgo = new Date(now.getTime() - (30 * 24 * 60 * 60 * 1000));
    const sixtyDaysAgo = new Date(now.getTime() - (60 * 24 * 60 * 60 * 1000));

    const currentPeriod = items.filter(item => {
      const date = new Date(item[dateField]);
      return date >= thirtyDaysAgo && date <= now;
    }).length;

    const previousPeriod = items.filter(item => {
      const date = new Date(item[dateField]);
      return date >= sixtyDaysAgo && date < thirtyDaysAgo;
    }).length;

    if (previousPeriod === 0) return currentPeriod > 0 ? '+100%' : '0%';
    const growth = ((currentPeriod - previousPeriod) / previousPeriod) * 100;
    return `${growth > 0 ? '+' : ''}${growth.toFixed(1)}%`;
  };

  const adminStats = useSelector((state) => state.content.stats);
  const aboutData = useSelector((state) => state.content.about);

  useEffect(() => {
    if (opportunities.length > 0) {
      setOpportunityGrowth(calculateGrowth(opportunities));
    }
  }, [opportunities]);

  // Auto-sync High Water Mark Stats (Live but never decrease)
  useEffect(() => {
    const syncLifetimeStats = async () => {
      if (!adminStats || !opportunities.length || !users.length) return;

      let statsChanged = false;
      const updatedStats = adminStats.map(stat => {
        const label = stat.label?.toLowerCase() || '';
        let liveVal = 0;

        if (label.includes('member') || label.includes('user')) liveVal = users.length;
        else if (label.includes('opp') || label.includes('listing')) liveVal = opportunities.length;
        else return stat;

        const currentAdminNum = parseInt(String(stat.value).replace(/[^0-9]/g, '')) || 0;
        if (liveVal > currentAdminNum) {
          statsChanged = true;
          return { ...stat, value: `${liveVal.toLocaleString()}+` };
        }
        return stat;
      });

      if (statsChanged) {
        try {
          await supabaseService.updateSiteContent('stats', updatedStats);
        } catch (e) {
          console.error("Failed to sync lifetime stats:", e);
        }
      }

      // Sync About Page Hero Stats too
      if (aboutData?.hero?.stats) {
        let aboutChanged = false;
        const updatedAboutHeroStats = aboutData.hero.stats.map(s => {
          const label = s.label?.toLowerCase() || '';
          let liveVal = 0;
          if (label.includes('member') || label.includes('user')) liveVal = users.length;
          else if (label.includes('opp') || label.includes('listing')) liveVal = opportunities.length;
          else return s;

          const currentVal = parseInt(String(s.value).replace(/[^0-9]/g, '')) || 0;
          if (liveVal > currentVal) {
            aboutChanged = true;
            return { ...s, value: `${liveVal.toLocaleString()}+` };
          }
          return s;
        });

        if (aboutChanged) {
          try {
            const updatedAbout = {
              ...aboutData,
              hero: { ...aboutData.hero, stats: updatedAboutHeroStats }
            };
            await supabaseService.updateSiteContent('about', updatedAbout);
          } catch (e) {
            console.error("Failed to sync about lifetime stats:", e);
          }
        }
      }
    };

    if (activeTab === 'overview' && users.length > 0 && opportunities.length > 0) {
      syncLifetimeStats();
    }
  }, [opportunities.length, users.length, adminStats, aboutData, activeTab]);

  const fetchUsers = async () => {
    if (isLoadingUsers) return;
    setIsLoadingUsers(true);
    try {
      const baseProfiles = await supabaseService.getAdminUsers();
      let richProfiles = [];
      try {
        richProfiles = await supabaseService.getProfiles();
      } catch (err) {
        console.warn("Could not fetch rich profiles for merging", err);
      }

      const mappedUsers = baseProfiles.map(p => {
        const rich = richProfiles.find(rp => rp.id === p.id) || {};
        return {
          id: p.id,
          name: p.full_name || rich.full_name || 'Anonymous User',
          email: p.email || 'No email provided',
          role: rich.role || p.role || 'user',
          roles: rich.roles || p.roles || (p.role ? [p.role] : []),
          avatar: rich.avatar_url || p.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(p.full_name || 'U')}&background=random`,
          avatarAlt: p.full_name || 'User Avatar',
          joinedDate: p.created_at ? new Date(p.created_at).toLocaleDateString() : (rich.created_at ? new Date(rich.created_at).toLocaleDateString() : 'Unknown'),
          contributions: rich.contributions_count || p.contributions_count || 0,
          suspended: rich.suspended || p.suspended || false,
          created_at: p.created_at || rich.created_at,
          demographics: {
            gender: rich.gender || p.gender || 'Not specified',
            phone: rich.phone || p.phone || 'Not specified',
            ageRange: rich.age_range || p.age_range || 'Not specified',
            demography: rich.demography || p.demography || 'Not specified',
            country: rich.country || p.country || 'Not specified'
          }
        };
      });
      setUsers(mappedUsers);
      setUserGrowth(calculateGrowth(baseProfiles));
    } catch (error) {
      console.error("Error fetching admin users:", error);
    } finally {
      setIsLoadingUsers(false);
    }
  };

  const handleUpdateRole = async (userId, specificRole = null) => {
    const userToUpdate = users.find(u => u.id === userId);
    if (!userToUpdate) return;

    const roleFlow = ['user', 'contributor', 'curator', 'tutor', 'ambassador', 'admin', 'founder'];
    const currentRole = userToUpdate.role || (userToUpdate.roles?.[0]) || 'user';
    const nextRole = specificRole || roleFlow[(roleFlow.indexOf(currentRole) + 1) % roleFlow.length];

    setConfirmConfig({
      isOpen: true,
      title: 'Update User Role',
      message: `Change ${userToUpdate.name}'s role to ${nextRole}?`,
      type: 'info',
      confirmText: 'Update Role',
      onConfirm: async () => {
        try {
          await supabaseService.updateProfileRole(userId, nextRole);
          setUsers(users.map(u => u.id === userId ? { ...u, role: nextRole, roles: [nextRole] } : u));
          addToast("Role updated successfully!", "success");
        } catch (error) {
          addToast("Failed to update role", "error");
        }
        setConfirmConfig(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  const handleToggleSuspension = async (userId) => {
    const userToToggle = users.find(u => u.id === userId);
    if (!userToToggle) return;
    const newSuspendedState = !userToToggle.suspended;
    const action = newSuspendedState ? 'suspend' : 'unsuspend';

    setConfirmConfig({
      isOpen: true,
      title: `${action.charAt(0).toUpperCase() + action.slice(1)} User`,
      message: `Are you sure you want to ${action} ${userToToggle.name}?`,
      type: newSuspendedState ? 'danger' : 'warning',
      confirmText: action.charAt(0).toUpperCase() + action.slice(1),
      onConfirm: async () => {
        try {
          await supabaseService.updateToggleProfileSuspension(userId, newSuspendedState);
          setUsers(users.map(u => u.id === userId ? { ...u, suspended: newSuspendedState } : u));
          addToast(`User ${action}ed successfully`, "success");
        } catch (error) {
          addToast(`Failed to ${action} user`, "error");
        }
        setConfirmConfig(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  const academyCourses = useSelector((state) => state.content.academy) || [];
  const vaultLessons = useSelector((state) => state.content.vault) || [];

  const statsData = [
    {
      title: "Total Opportunities",
      value: opportunities.length.toLocaleString(),
      change: opportunityGrowth,
      changeType: opportunityGrowth.startsWith('+') ? "positive" : (opportunityGrowth === '0%' ? 'neutral' : 'negative'),
      icon: "Briefcase",
      iconBg: "bg-gradient-to-br from-secondary to-brand-blue"
    },
    {
      title: "Academy Courses",
      value: academyCourses.length.toLocaleString(),
      change: "+2 new",
      changeType: "positive",
      icon: "GraduationCap",
      iconBg: "bg-gradient-to-br from-secondary to-purple-500"
    },
    {
      title: "Active Community Members",
      value: isLoadingUsers ? "..." : users.length.toLocaleString(),
      change: userGrowth,
      changeType: userGrowth.startsWith('+') ? "positive" : (userGrowth === '0%' ? 'neutral' : 'negative'),
      icon: "Users",
      iconBg: "bg-gradient-to-br from-success to-secondary"
    },
    {
      title: "Vault Lessons",
      value: vaultLessons.length.toLocaleString(),
      change: "+5 this week",
      changeType: "positive",
      icon: "Zap",
      iconBg: "bg-gradient-to-br from-yellow-400 to-orange-500"
    },
    {
      title: "Saved Items",
      value: savedItemsCount.toLocaleString(),
      change: savedGrowth,
      changeType: savedGrowth.startsWith('+') ? "positive" : (savedGrowth === '0%' ? 'neutral' : 'negative'),
      icon: "Heart",
      iconBg: "bg-gradient-to-br from-success to-accent"
    }
  ];

  const quickActions = [
    {
      title: "Add Opportunity",
      description: "Create a new listing",
      icon: "Plus",
      iconBg: "bg-gradient-to-br from-success to-secondary",
      onClick: () => {
        setActiveTab('opportunities');
        setEditingOpportunity(null);
        setIsModalOpen(true);
      }
    },
    {
      title: "Review Partnerships",
      description: "Manage new proposals",
      icon: "Handshake",
      iconBg: "bg-gradient-to-br from-brand-blue to-accent",
      onClick: () => setActiveTab('partnerships')
    },
    {
      title: "New Submission",
      description: "Approve community posts",
      icon: "UploadCloud",
      iconBg: "bg-gradient-to-br from-secondary to-success",
      onClick: () => setActiveTab('submissions')
    },
    {
      title: "Manage Academy",
      description: "Update course catalog",
      icon: "GraduationCap",
      iconBg: "bg-gradient-to-br from-purple-500 to-secondary",
      onClick: () => setActiveTab('academy')
    },
    {
      title: "Update Vault",
      description: "Add new Quick Wins",
      icon: "Zap",
      iconBg: "bg-gradient-to-br from-yellow-400 to-orange-500",
      onClick: () => setActiveTab('vault')
    }
  ];

  const handleEditOpportunity = (id) => {
    const opp = opportunities.find(o => o.id === id);
    if (opp) {
      setEditingOpportunity(opp);
      setIsModalOpen(true);
    }
  };

  const handleDeleteOpportunity = (id) => {
    setConfirmConfig({
      isOpen: true,
      title: 'Delete Opportunity',
      message: 'Are you sure you want to delete this opportunity? This action cannot be undone.',
      type: 'danger',
      confirmText: 'Delete',
      onConfirm: async () => {
        try {
          await dispatch(deleteOpportunityAsync(id)).unwrap();
          addToast("Opportunity deleted successfully", "success");
        } catch (error) {
          addToast("Failed to delete opportunity", "error");
        }
        setConfirmConfig(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  const handleToggleTrending = (id) => {
    const opp = opportunities.find(o => o.id === id);
    if (opp) {
      dispatch(updateOpportunityAsync({ ...opp, trending: !opp.trending }));
    }
  };

  const handlePromoteSubmission = (submission) => {
    const normalizeCategory = (cat) => {
      const c = cat?.toLowerCase() || '';
      if (c.includes('scholarship')) return 'scholarships';
      if (c.includes('internship')) return 'internships';
      if (c.includes('fellowship')) return 'fellowships';
      if (c.includes('competition') || c.includes('contest')) return 'competitions';
      if (c.includes('workshop')) return 'workshops';
      if (c.includes('conference')) return 'conferences';
      if (c.includes('job')) return 'jobs';
      return 'scholarships';
    };

    const mappedOpportunity = {
      title: submission.title,
      organization: submission.organization,
      category: normalizeCategory(submission.category),
      detailedDescription: submission.description,
      shortDescription: submission.description?.substring(0, 150) + '...',
      applicationLink: submission.application_link,
      deadline: submission.deadline,
      status: 'active',
      verified: true,
      _fromSubmissionId: submission.id
    };

    setEditingOpportunity(mappedOpportunity);
    setIsModalOpen(true);
  };

  const handleModalSubmit = async (data) => {
    try {
      const { _fromSubmissionId, ...opportunityData } = data;
      if (editingOpportunity && editingOpportunity.id) {
        await dispatch(updateOpportunityAsync({ ...editingOpportunity, ...opportunityData })).unwrap();
      } else {
        await dispatch(addOpportunityAsync({
          ...opportunityData,
          views: 0,
          applicants: 0,
          daysLeft: 30,
          created_at: new Date().toISOString()
        })).unwrap();
        const submissionId = _fromSubmissionId || editingOpportunity?._fromSubmissionId;
        if (submissionId) {
          await supabaseService.updateSubmissionStatus(submissionId, 'approved');
          addToast("Submission marked as approved and published!", "success");
        }
      }
      setIsModalOpen(false);
      setEditingOpportunity(null);
      addToast("Opportunity saved successfully!", "success");
    } catch (error) {
      addToast("Failed to save opportunity", "error");
    }
  };

  const openAddModal = () => {
    setEditingOpportunity(null);
    setIsModalOpen(true);
  };

  const handleDeleteUser = async (userId) => {
    const userToDelete = users.find(u => u.id === userId);
    if (!userToDelete) return;
    setConfirmConfig({
      isOpen: true,
      title: 'Delete User Account',
      message: `Are you sure you want to delete ${userToDelete.name}? This action is permanent.`,
      type: 'danger',
      confirmText: 'Delete Permanently',
      onConfirm: async () => {
        try {
          await supabaseService.deleteProfile(userId);
          setUsers(users.filter(u => u.id !== userId));
          addToast("User profile deleted successfully", "success");
        } catch (error) {
          addToast("Failed to delete user profile", "error");
        }
        setConfirmConfig(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  const maintenanceMode = useSelector(state => state.content.maintenanceMode);
  const [isMaintenanceActive, setIsMaintenanceActive] = useState(false);
  const [maintenanceForm, setMaintenanceForm] = useState({
    title: '',
    message: '',
    estimatedReturn: ''
  });

  useEffect(() => {
    if (maintenanceMode) {
      setIsMaintenanceActive(maintenanceMode.active);
      setMaintenanceForm({
        title: maintenanceMode.title || '',
        message: maintenanceMode.message || '',
        estimatedReturn: maintenanceMode.estimatedReturn || ''
      });
    }
  }, [maintenanceMode]);

  const handleSaveMaintenanceContent = () => {
    dispatch(updateMaintenanceModeAsync({
      ...maintenanceMode,
      ...maintenanceForm
    })).then(() => {
      addToast("Maintenance page content updated successfully.", "success");
    }).catch((err) => {
      console.error("Failed to save maintenance content:", err);
      addToast("Failed to save refinement settings. Please try again.", "error");
    });
  };

  const handleToggleMaintenance = () => {
    const newState = !isMaintenanceActive;
    dispatch(updateMaintenanceModeAsync({
      ...maintenanceMode,
      active: newState
    })).then(() => {
      addToast(
        newState 
          ? "Institutional Refinement Mode Activated. Platform is now shielded." 
          : "Refinement Mode Deactivated. Platform is now LIVE.",
        newState ? "warning" : "success"
      );
    }).catch((err) => {
      console.error("Failed to toggle maintenance mode:", err);
      addToast("Failed to toggle Refinement Mode. Please try again.", "error");
    });
  };

  const navigationGroups = [
    {
      group: 'PLATFORM CORE',
      tabs: [
        { id: 'overview', label: 'Overview', icon: 'LayoutDashboard' },
        { id: 'users', label: 'Users', icon: 'Users' },
        { id: 'recruitment', label: 'Elite Recruitment', icon: 'UserPlus' },
        { id: 'analytics', label: 'Analytics', icon: 'BarChart' },
        { id: 'system', label: 'System Controls', icon: 'ShieldCheck' },
      ]
    },
    {
      group: 'TALENT & OPPORTUNITIES',
      tabs: [
        { id: 'opportunities', label: 'Opportunities', icon: 'Briefcase' },
        { id: 'submissions', label: 'Submissions', icon: 'UploadCloud' },
        { id: 'referrals', label: 'Referrals Hub', icon: 'UserPlus' },
        { id: 'ventures', label: 'Ventures & Verification', icon: 'Rocket' },
        { id: 'syndicate', label: 'Investor Syndicate', icon: 'DollarSign' },
      ]
    },
    {
      group: 'ACADEMY OPERATIONS',
      tabs: [
        { id: 'academy', label: 'Academy', icon: 'GraduationCap' },
        { id: 'scholarships', label: 'Scholarships', icon: 'Gift' },
        { id: 'course-drafts', label: 'Course Drafts', icon: 'BookOpen' },
        { id: 'live-sessions', label: 'Live Sessions', icon: 'Video' },
        { id: 'instructors', label: 'Instructors', icon: 'Users' },
        { id: 'instructor-applications', label: 'Instructor Apps', icon: 'FileText' },
        { id: 'requests', label: 'Course Requests', icon: 'Lightbulb' },
        { id: 'camp-parents', label: 'Camp Parents', icon: 'MessageCircle' },
        { id: 'attendance', label: 'Attendance Register', icon: 'ClipboardCheck' },
        { id: 'track-attendance', label: 'Track Attendance Overview', icon: 'BarChart' },
        { id: 'track-schedule', label: 'Track Course Schedule', icon: 'Calendar' },
        { id: 'coursework', label: 'Assignments & Assessments', icon: 'FileText' },
        { id: 'payments', label: 'Payment Management', icon: 'CreditCard' },
      ]
    },
    {
      group: 'COMMUNITY & CONTENT',
      tabs: [
        { id: 'content', label: 'Homepage', icon: 'Home' },
        { id: 'about', label: 'About Page', icon: 'Info' },
        { id: 'newsletter', label: 'Newsletter Control', icon: 'Send' },
        { id: 'inbox', label: 'Inbox', icon: 'Mail' },
        { id: 'partnerships', label: 'Partnerships', icon: 'Handshake' },
        { id: 'vault', label: 'Vault', icon: 'Zap' },
        { id: 'reviews', label: 'Reviews', icon: 'MessageSquare' },
        { id: 'spotlights', label: 'Hall of Fame', icon: 'Award' },
      ]
    },
    {
      group: 'LOGISTICS & REWARDS',
      tabs: [
        { id: 'payouts', label: 'Payout Queue', icon: 'DollarSign' },
        { id: 'store', label: 'Store Manager', icon: 'ShoppingBag' },
        { id: 'promo-codes', label: 'Promo Codes', icon: 'Tag' },
        { id: 'rewards', label: 'Rewards Queue', icon: 'Gift' },
        { id: 'peer-ratings', label: 'Peer Ratings', icon: 'Star' },
        { id: 'mentorship-oversight', label: 'Mentorship Audit', icon: 'Eye' },
      ]
    },
    {
      group: 'GOVERNANCE',
      tabs: [
        { id: 'audit', label: 'Security & Audits', icon: 'ShieldAlert' }
      ]
    }
  ];

  const renderTabContent = () => {
    switch(activeTab) {
        case 'overview': return (
            <div className="space-y-10">
                <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-4">
                    {statsData.map((stat, idx) => (
                        <StatsCard key={idx} {...stat} />
                    ))}
                </div>
                
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    <AnalyticsChart />
                    <div className="bg-card border border-border rounded-[2.5rem] p-8 shadow-xl">
                        <h3 className="text-xl font-black italic tracking-tight uppercase mb-6 flex items-center gap-2">
                            <Icon name="Activity" size={20} className="text-primary" />
                            Recent Activity
                        </h3>
                        <div className="space-y-4 max-h-[400px] overflow-y-auto custom-scrollbar pr-2">
                            <RecentActivityItem icon="UserPlus" title="New Instructor Joined" time="2 hours ago" description="Sarah Jenkins completed faculty verification." />
                            <RecentActivityItem icon="CheckCircle" title="Submission Approved" time="4 hours ago" description="Tech Fellowship 2024 is now LIVE." />
                            <RecentActivityItem icon="Shield" title="Security Alert" time="12 hours ago" description="Blocked 4 consecutive failed login attempts." />
                        </div>
                    </div>
                </div>

                <div>
                    <h3 className="text-2xl font-black italic tracking-tight uppercase mb-6">Quick Operations</h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
                        {quickActions.map((action, idx) => (
                            <QuickActionCard key={idx} {...action} />
                        ))}
                    </div>
                </div>
            </div>
        );
        case 'users': return <UserManagementPanel users={users} onUpdateRole={handleUpdateRole} onSuspend={handleToggleSuspension} onDelete={handleDeleteUser} onRefresh={fetchUsers} isLoading={isLoadingUsers} />;
        case 'recruitment': return <BuilderApplications />;
        case 'analytics': return <AnalyticsManagement />;
        case 'system': return (
            <div className="space-y-12 max-w-5xl">
                {/* Global Toggles */}
                <SystemSettings />

                {/* Maintenance Mode */}
                <div className="bg-card border border-border rounded-[2.5rem] p-10 shadow-2xl relative overflow-hidden group">
                    <div className="absolute inset-0 bg-amber-500/5 opacity-0 group-hover:opacity-100 transition-opacity" />
                    
                    <div className="relative z-10">
                        <div className="flex items-center justify-between mb-10">
                            <div>
                                <h2 className="text-3xl font-black text-slate-900 dark:text-white uppercase italic tracking-tighter">Refinement Mode</h2>
                                <p className="text-sm text-slate-500 font-medium">Toggle global maintenance state and shielding.</p>
                            </div>
                            <button
                                onClick={handleToggleMaintenance}
                                className={cn(
                                    "w-20 h-10 rounded-full transition-all duration-500 relative",
                                    isMaintenanceActive ? "bg-amber-500 shadow-lg shadow-amber-500/30" : "bg-slate-200 dark:bg-white/10"
                                )}
                            >
                                <div className={cn(
                                    "absolute top-1.5 w-7 h-7 rounded-full bg-white shadow-xl transition-all duration-500",
                                    isMaintenanceActive ? "left-11" : "left-1.5"
                                )} />
                            </button>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                            <div className="space-y-3">
                                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/60 ml-2">Shield Title</label>
                                <input value={maintenanceForm.title} onChange={(e) => setMaintenanceForm({...maintenanceForm, title: e.target.value})} className="w-full bg-slate-100 dark:bg-white/5 border border-border rounded-2xl p-4 font-bold focus:ring-2 focus:ring-primary outline-none transition-all" placeholder="Institutional Refinement..." />
                            </div>
                            <div className="space-y-3">
                                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/60 ml-2">Restoration Time</label>
                                <input value={maintenanceForm.estimatedReturn} onChange={(e) => setMaintenanceForm({...maintenanceForm, estimatedReturn: e.target.value})} className="w-full bg-slate-100 dark:bg-white/5 border border-border rounded-2xl p-4 font-bold focus:ring-2 focus:ring-primary outline-none transition-all" placeholder="2 hours..." />
                            </div>
                            <div className="col-span-full space-y-3">
                                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/60 ml-2">Broadcast Message</label>
                                <textarea value={maintenanceForm.message} onChange={(e) => setMaintenanceForm({...maintenanceForm, message: e.target.value})} className="w-full bg-slate-100 dark:bg-white/5 border border-border rounded-2xl p-4 font-bold focus:ring-2 focus:ring-primary outline-none transition-all min-h-[120px]" placeholder="We are refining the platform for better performance..." />
                            </div>
                        </div>
                        <button onClick={handleSaveMaintenanceContent} className="w-full py-5 bg-slate-900 text-white font-black italic rounded-[1.5rem] shadow-2xl hover:bg-primary transition-all uppercase tracking-widest text-xs">SYNC REFINEMENT SETTINGS</button>
                    </div>
                </div>
            </div>
        );
        case 'opportunities': return <OpportunityManagementTable opportunities={opportunities} onEdit={handleEditOpportunity} onDelete={handleDeleteOpportunity} onToggleTrending={handleToggleTrending} onAdd={openAddModal} />;
        case 'content': return <ContentManagement />;
        case 'about': return <AboutManagement />;
        case 'inbox': return <MessageManagement />;
        case 'partnerships': return <PartnershipManagement />;
        case 'submissions': return <SubmissionManagement onPromote={handlePromoteSubmission} />;
        case 'academy': return <AcademyManagement />;
        case 'instructors': return <InstructorManagement />;
        case 'vault': return <VaultManagement />;
        case 'reviews': return <ReviewsManagement />;
        case 'requests': return <CourseRequestManagement />;
        case 'instructor-applications': return <InstructorApplications />;
        case 'audit': return <AuditManagement />;
        case 'peer-ratings': return <PeerRatingsManagement />;
        case 'scholarships': return <ScholarshipManagement />;
        case 'live-sessions': return <LiveSessionManagement />;
        case 'payouts': return <AdminPayoutControl />;
        case 'mentorship-oversight': return <MentorshipOversight />;
        case 'course-drafts': return <CourseDraftReview />;
        case 'spotlights': return <SpotlightManagement />;
        case 'referrals': return <ReferralManagement />;
        case 'ventures': return <VentureOversight />;
        case 'rewards': return <RewardManagement />;
        case 'promo-codes': return <PlatformPromoManagement />;
        case 'store': return <StoreManagement />;
        case 'newsletter': return <NewsletterManagement />;
        case 'syndicate': return <SyndicateManagement />;
        case 'camp-parents': return <CampParentNotifications />;
        case 'attendance': return <CourseAttendance />;
        case 'track-attendance': return <TrackAttendanceOverview />;
        case 'track-schedule': return <TrackCourseSchedule />;
        case 'coursework': return <CourseWorkRegister />;
        case 'payments': return <PaymentManagement />;
        default: return null;
    }
  };

  const allTabs = navigationGroups.flatMap(g => g.tabs);

  if (checkingMfa) {
    return (
        <div className="min-h-screen bg-background flex flex-col items-center justify-center" data-security-clearance="true">
            <Icon name="ShieldCheck" size={48} className="text-primary animate-pulse mb-4" />
            <p className="font-bold tracking-widest uppercase text-muted-foreground">Verifying Security Clearance...</p>
        </div>
    );
  }

  if (!mfaVerified) {
    return (
        <div className="min-h-screen bg-background flex flex-col font-sans selection:bg-primary/30">
            <Header />
            <div className="flex-1 flex items-center justify-center p-4 py-12">
                 <div className="max-w-2xl w-full bg-card border border-destructive/30 rounded-[2.5rem] p-8 md:p-12 shadow-2xl shadow-destructive/10 relative overflow-hidden text-center space-y-8 animate-in zoom-in-95 duration-500">
                     <div className="absolute top-0 right-0 w-64 h-64 bg-destructive/5 rounded-full blur-[80px] -translate-y-1/2 translate-x-1/2 pointer-events-none" />
                     
                     <div className="w-24 h-24 bg-destructive/10 rounded-[2.5rem] flex items-center justify-center mx-auto text-destructive shadow-inner border border-destructive/20 relative z-10">
                         <Icon name="ShieldAlert" size={48} />
                     </div>
                     
                     <div className="relative z-10">
                         <h2 className="text-3xl md:text-4xl font-black italic tracking-tighter uppercase mb-3">Institutional Security</h2>
                         <p className="text-muted-foreground font-medium text-lg max-w-lg mx-auto">
                             As an administrator, you are <strong className="text-foreground">required</strong> to enable Multi-Factor Authentication (MFA) to safeguard the platform's integrity.
                         </p>
                     </div>
                     
                     <div className="text-left bg-background border border-border rounded-2xl p-6 relative z-10 shadow-sm">
                         <MfaSettings onStatusChange={(isActive) => {
                             if (isActive) setMfaVerified(true);
                         }} />
                     </div>

                     <div className="pt-4 border-t border-border relative z-10">
                         <Button variant="ghost" onClick={() => window.location.href = '/'} className="font-bold tracking-widest uppercase text-xs">Return to Public Site</Button>
                     </div>
                 </div>
            </div>
            <Footer />
        </div>
    );
  }

  return (
    <div className="min-h-screen bg-background flex flex-col font-sans selection:bg-primary/30 overflow-hidden">
      <Header />
      <div className="flex-1 flex overflow-hidden">
        
        <AnimatePresence>
            {isSidebarOpen && (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-background/80 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />
            )}
        </AnimatePresence>

        <aside className={cn(
            "fixed lg:static top-16 sm:top-20 lg:top-0 left-0 z-50 w-72 bg-card border-r border-border transition-all duration-500 ease-in-out flex flex-col h-[calc(100vh-4rem)] sm:h-[calc(100vh-5rem)] lg:h-[calc(100vh-6rem)] shadow-2xl lg:shadow-none",
            isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
        )}>
          <div className="p-8 relative">
            <h2 className="text-2xl font-black italic tracking-tighter flex items-center gap-3">
              <div className="p-2 bg-primary/10 rounded-lg"><Icon name="Shield" size={20} className="text-primary" /></div>
              ADMIN CP
            </h2>
            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground mt-2 opacity-60">Elite Platform Control</p>
          </div>

          <nav className="flex-1 overflow-y-auto custom-scrollbar px-4 pb-12 space-y-8">
            {navigationGroups.map((group, idx) => (
              <div key={idx} className="space-y-2">
                <h3 className="px-4 text-[9px] font-black uppercase tracking-[0.3em] text-primary/40 mb-3">{group.group}</h3>
                <div className="space-y-1">
                    {group.tabs.map((tab) => (
                    <button key={tab.id} onClick={() => { setActiveTab(tab.id); setIsSidebarOpen(false); }} className={cn("w-full flex items-center gap-3 px-4 py-3 rounded-2xl text-xs font-black italic transition-all duration-300 relative group", activeTab === tab.id ? 'text-primary' : 'text-muted-foreground hover:text-foreground hover:bg-muted/50')}>
                        {activeTab === tab.id && <motion.div layoutId="activeTabAdmin" className="absolute inset-0 bg-primary/5 border border-primary/20 rounded-2xl -z-10" transition={{ type: "spring", bounce: 0.2, duration: 0.6 }} />}
                        <Icon name={tab.icon} size={18} className={cn("transition-colors", activeTab === tab.id ? "text-primary" : "group-hover:text-primary")} />
                        <span className="uppercase tracking-widest">{tab.label}</span>
                        {tab.id === 'inbox' && unreadMessages > 0 && <span className="ml-auto bg-primary text-white text-[8px] font-black px-1.5 py-0.5 rounded-full">{unreadMessages}</span>}
                        {tab.id === 'course-drafts' && pendingDrafts > 0 && <span className="ml-auto bg-brand-blue text-white text-[8px] font-black px-1.5 py-0.5 rounded-full">{pendingDrafts}</span>}
                    </button>
                    ))}
                </div>
              </div>
            ))}
          </nav>
        </aside>

        <main className="flex-1 overflow-y-auto custom-scrollbar h-[calc(100vh-4rem)] sm:h-[calc(100vh-5rem)] lg:h-[calc(100vh-6rem)] bg-muted/5 relative">
          
          <motion.button 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1, x: isSidebarOpen ? 288 : 0 }}
            transition={{ type: "spring", damping: 20, stiffness: 100 }}
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.9 }}
            className="lg:hidden fixed left-0 top-[45%] z-[60] p-3 pr-4 bg-primary text-white rounded-r-3xl shadow-2xl shadow-primary/40 flex items-center justify-center border-y border-r border-white/10 transition-colors"
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          >
            <Icon name={isSidebarOpen ? "ChevronLeft" : "ChevronRight"} size={24} />
          </motion.button>

          <div className="max-w-7xl mx-auto p-4 sm:p-8 lg:p-12">
            <div className="mb-12">
              <div className="flex flex-col gap-3">
                <div className="flex items-center gap-3">
                    <div className="h-1 w-12 bg-primary rounded-full" />
                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-primary">Institutional Core</span>
                </div>
                <h1 className="text-4xl md:text-5xl font-black italic tracking-tighter uppercase leading-none">
                  {allTabs.find(t => t.id === activeTab)?.label || activeTab}
                </h1>
                <p className="text-muted-foreground font-bold italic text-sm md:text-base max-w-2xl opacity-70">
                    {activeTab === 'overview' && 'Strategic oversight of the LUC ecosystem. Impact metrics synchronized.'}
                    {activeTab === 'users' && 'Manage the sovereign community of LUC scholars and contributors.'}
                    {activeTab === 'system' && 'Configure global refinement protocols and platform shielding.'}
                    {activeTab === 'opportunities' && 'Architecture and management of the global opportunity stream.'}
                </p>
              </div>
            </div>

            <div className="min-h-[60vh] relative">
                <AnimatePresence mode="wait">
                    <motion.div key={activeTab} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.3, ease: "easeOut" }}>
                        {renderTabContent()}
                    </motion.div>
                </AnimatePresence>
            </div>
          </div>
          <Footer />
        </main>
      </div>

      <OpportunityModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSubmit={handleModalSubmit} initialData={editingOpportunity} />
      <ConfirmationModal isOpen={confirmConfig.isOpen} onClose={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} onConfirm={confirmConfig.onConfirm} title={confirmConfig.title} message={confirmConfig.message} type={confirmConfig.type} confirmText={confirmConfig.confirmText} />
    </div>
  );
};

export default AdminDashboard;
