import React, { useState, useEffect, useRef } from 'react';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import Select from '../../../components/ui/Select';
import StudentDetailView from './StudentDetailView';

const UserManagementPanel = ({ users, onUpdateRole, onSuspend, onDelete, onRefresh, isLoading }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [roleFilter, setRoleFilter] = useState('all');
  const [selectedStudent, setSelectedStudent] = useState(null);
  const [editingUserRole, setEditingUserRole] = useState(null);

  const roleOptions = [
    { value: 'all', label: 'All Roles' },
    { value: 'founder', label: 'Founder' },
    { value: 'admin', label: 'Admin' },
    { value: 'stealth', label: 'Stealth Admin' },
    { value: 'contributor', label: 'Community Contributor' },
    { value: 'curator', label: 'Opportunity Curator' },
    { value: 'tutor', label: 'Guest Tutor' },
    { value: 'ambassador', label: 'Student Ambassador' },
    { value: 'user', label: 'Scholar' }
  ];

  const filteredUsers = users?.filter(user => {
    const matchesSearch = user?.name?.toLowerCase()?.includes(searchQuery?.toLowerCase()) ||
      user?.email?.toLowerCase()?.includes(searchQuery?.toLowerCase());

    // Support both single role and array of roles
    const userRoles = Array.isArray(user?.roles) ? user.roles : (user?.role ? [user.role] : []);
    const matchesRole = roleFilter === 'all' || userRoles.includes(roleFilter);
    return matchesSearch && matchesRole;
  });

  const getRoleBadges = (user) => {
    const roles = Array.isArray(user?.roles) ? user.roles : (user?.role ? [user.role] : []);

    const roleConfig = {
      founder: { bg: 'bg-primary/20', text: 'text-primary', label: 'Founder', icon: 'Crown' },
      admin: { bg: 'bg-red-500/10', text: 'text-red-500', label: 'Admin', icon: 'Shield' },
      stealth: { bg: 'bg-zinc-500/20', text: 'text-zinc-400', label: 'Stealth Admin', icon: 'Ghost' },
      contributor: { bg: 'bg-blue-500/10', text: 'text-blue-500', label: 'Contributor', icon: 'Users' },
      curator: { bg: 'bg-green-500/10', text: 'text-green-500', label: 'Curator', icon: 'Search' },
      tutor: { bg: 'bg-purple-500/10', text: 'text-purple-500', label: 'Tutor', icon: 'BookOpen' },
      ambassador: { bg: 'bg-orange-500/10', text: 'text-orange-500', label: 'Ambassador', icon: 'Award' },
      user: { bg: 'bg-muted', text: 'text-muted-foreground', label: 'Scholar', icon: 'User' }
    };

    if (roles.length === 0) {
      roles.push('user');
    }

    return (
      <div className="flex flex-wrap gap-1">
        {roles.map(role => {
          const config = roleConfig?.[role] || roleConfig?.user;
          return (
            <span key={role} className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider ${config?.bg} ${config?.text}`}>
              {config.icon && <Icon name={config.icon} size={10} />}
              {config?.label}
            </span>
          );
        })}
      </div>
    );
  };

  if (selectedStudent) {
    return (
      <StudentDetailView
        user={selectedStudent}
        onBack={() => setSelectedStudent(null)}
      />
    );
  }

  return (
    <div className="bg-card rounded-2xl shadow-[0_4px_12px_rgba(27,54,93,0.08)] p-4 md:p-6 overflow-hidden">
      <div className="p-4 md:p-6 border-b border-border">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-6">
          <h2 className="text-xl sm:text-2xl font-bold text-foreground">User Management</h2>
          <button
            onClick={onRefresh}
            className="w-11 h-11 flex items-center justify-center hover:bg-muted rounded-lg transition-colors text-muted-foreground hover:text-primary"
            title="Refresh User Data"
          >
            <Icon name="RefreshCw" size={20} className={isLoading ? 'animate-spin' : ''} />
          </button>
        </div>

        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 w-full">
            <Input
              type="search"
              placeholder="Search users..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e?.target?.value)}
            />
          </div>
          <div className="w-full md:w-48">
            <Select
              options={roleOptions}
              value={roleFilter}
              onChange={setRoleFilter}
              placeholder="Filter by role"
            />
          </div>
        </div>
      </div>
      <div className="p-4 md:p-6">
        <div className="space-y-3">
          {filteredUsers?.map((user) => (
            <div
              key={user?.id}
              className="flex flex-col sm:flex-row sm:items-center gap-4 p-4 rounded-xl border border-border hover:bg-muted/30 transition-colors"
            >
              <div className="flex items-center gap-4 flex-1 min-w-0">
                <Image
                  src={user?.avatar}
                  alt={user?.avatarAlt}
                  className="w-12 h-12 rounded-full object-cover flex-shrink-0"
                />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1 flex-wrap">
                    <h4 className="font-bold text-foreground line-clamp-1">{user?.name}</h4>
                    {getRoleBadges(user)}
                  </div>
                  <p className="text-sm text-muted-foreground line-clamp-1 truncate">{user?.email}</p>
                  {user?.demographics && (
                    <div className="flex flex-wrap gap-1.5 text-[10px] text-muted-foreground mt-1.5">
                      {user.demographics.gender && user.demographics.gender !== 'Not specified' && <span className="bg-muted px-1.5 py-0.5 rounded">{user.demographics.gender}</span>}
                      {user.demographics.ageRange && user.demographics.ageRange !== 'Not specified' && <span className="bg-muted px-1.5 py-0.5 rounded">{user.demographics.ageRange}</span>}
                      {user.demographics.demography && user.demographics.demography !== 'Not specified' && <span className="bg-muted px-1.5 py-0.5 rounded max-w-[120px] truncate" title={user.demographics.demography}>{user.demographics.demography}</span>}
                      {user.demographics.country && user.demographics.country !== 'Not specified' && <span className="bg-muted px-1.5 py-0.5 rounded flex items-center gap-1"><Icon name="MapPin" size={8} />{user.demographics.country}</span>}
                      {user.demographics.phone && user.demographics.phone !== 'Not specified' && <span className="bg-muted px-1.5 py-0.5 rounded flex items-center gap-1"><Icon name="Phone" size={8} />{user.demographics.phone}</span>}
                    </div>
                  )}
                </div>
              </div>

              <div className="flex flex-col sm:flex-col lg:flex-row items-start sm:items-end lg:items-center justify-between sm:justify-center gap-3 pt-3 sm:pt-0 border-t sm:border-0 border-border/50 w-full sm:w-auto">
                <div className="flex flex-col sm:items-end text-xs text-muted-foreground w-full sm:w-auto">
                  <div className="flex items-center gap-2 sm:justify-end">
                    <Icon name="Calendar" size={12} />
                    <span>{user?.joinedDate}</span>
                  </div>
                  <div className="flex items-center gap-2 mt-1 font-medium text-primary/80">
                    <Icon name="Award" size={12} />
                    <span>{user?.contributions} contributions</span>
                  </div>
                </div>

                <div className="flex items-center justify-end w-full sm:w-auto gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    iconName="BarChart2"
                    onClick={(e) => {
                      e.stopPropagation();
                      setSelectedStudent(user);
                    }}
                    title="View Student Progress"
                  />
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    iconName="Shield"
                    onClick={(e) => {
                      e.stopPropagation();
                      setEditingUserRole(user);
                    }}
                    title="Change Role"
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    iconName={user?.suspended ? 'UserCheck' : 'UserX'}
                    onClick={(e) => {
                      e.stopPropagation();
                      onSuspend(user?.id);
                    }}
                    title={user?.suspended ? 'Unsuspend' : 'Suspend'}
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    iconName="Trash2"
                    className="text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20"
                    onClick={(e) => {
                      e.stopPropagation();
                      onDelete(user?.id);
                    }}
                    title="Delete User"
                  />
                </div>
              </div>
            </div>
          ))}
        </div>

        {filteredUsers?.length === 0 && (
          <div className="text-center py-12">
            <Icon name="Users" size={48} color="var(--color-muted-foreground)" className="mx-auto mb-4" />
            <p className="text-muted-foreground">No users found matching your criteria</p>
          </div>
        )}
      </div>

      {/* Role Selection Modal */}
      {editingUserRole && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-background/80 backdrop-blur-md animate-in fade-in duration-300"
            onClick={() => setEditingUserRole(null)}
          />
          <div className="relative w-full max-w-sm bg-card border border-border rounded-[2rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 slide-in-from-bottom-8 duration-300">
            <div className="p-4 md:p-6 border-b border-border bg-muted/30">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-primary/10 rounded-xl">
                    <Icon name="Shield" size={20} className="text-primary" />
                  </div>
                  <div>
                    <h3 className="font-black text-foreground">Update Access</h3>
                    <p className="text-[10px] text-muted-foreground uppercase tracking-widest leading-tight">Privilege Management</p>
                  </div>
                </div>
                <button
                  onClick={() => setEditingUserRole(null)}
                  className="w-11 h-11 flex items-center justify-center hover:bg-muted rounded-full transition-colors"
                >
                  <Icon name="X" size={20} className="text-muted-foreground" />
                </button>
              </div>

              <div className="flex items-center gap-3 p-3 bg-card border border-border rounded-2xl">
                <Image src={editingUserRole.avatar} className="w-10 h-10 rounded-full" />
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold truncate">{editingUserRole.name}</p>
                  <p className="text-[10px] text-muted-foreground truncate">{editingUserRole.email}</p>
                </div>
              </div>
            </div>

            <div className="p-4 space-y-1 max-h-[50vh] overflow-y-auto">
              {(() => {
                const userRoles = Array.isArray(editingUserRole.roles) ? editingUserRole.roles : (editingUserRole.role ? [editingUserRole.role] : []);

                return roleOptions.filter(opt => opt.value !== 'all').map((opt) => (
                  <button
                    key={opt.value}
                    onClick={() => {
                      onUpdateRole(editingUserRole.id, opt.value);
                      setEditingUserRole(null);
                    }}
                    className={`w-full text-left px-4 py-3.5 rounded-2xl text-sm font-bold transition-all duration-300 flex items-center justify-between group
                      ${userRoles.includes(opt.value)
                        ? 'bg-primary text-primary-foreground shadow-lg shadow-primary/20 scale-[1.02]'
                        : 'text-muted-foreground hover:bg-muted hover:text-foreground'
                      }`}
                  >
                    <span className="flex items-center gap-3">
                      <div className={`p-1.5 rounded-lg ${userRoles.includes(opt.value) ? 'bg-white/20' : 'bg-muted group-hover:bg-card'}`}>
                        <Icon name={
                          opt.value === 'founder' ? 'Crown' :
                            opt.value === 'admin' ? 'Shield' :
                              opt.value === 'stealth' ? 'Ghost' :
                                opt.value === 'contributor' ? 'Users' :
                                  opt.value === 'curator' ? 'Search' :
                                    opt.value === 'tutor' ? 'BookOpen' :
                                      opt.value === 'ambassador' ? 'Award' : 'User'
                        } size={16} />
                      </div>
                      {opt.label}
                    </span>
                    {userRoles.includes(opt.value) && (
                      <Icon name="Check" size={18} />
                    )}
                  </button>
                ));
              })()}
            </div>

            <div className="p-4 md:p-6 bg-muted/20 border-t border-border">
              <p className="text-xs text-muted-foreground text-center font-medium">
                Changing access levels takes effect immediately across all sessions.
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserManagementPanel;