// ─── Countdown Clock ────────────────────────────────────────────────
const Countdown = ({ endsAt, onExpire }) => {
    const [remaining, setRemaining] = useState(0);

    useEffect(() => {
        const calc = () => {
            const diff = Math.max(0, Math.floor((new Date(endsAt) - Date.now()) / 1000));
            setRemaining(diff);
            if (diff === 0) onExpire?.();
        };
        calc();
        const id = setInterval(calc, 1000);
        return () => clearInterval(id);
    }, [endsAt, onExpire]);

    const m = String(Math.floor(remaining / 60)).padStart(2, '0');
    const s = String(remaining % 60).padStart(2, '0');
    const isUrgent = remaining < 60;

    return (
        <div className={`flex items-center gap-2 font-mono font-black text-xl tabular-nums ${isUrgent ? 'text-red-500 animate-pulse' : 'text-primary'}`}>
            <Icon name={isUrgent ? 'AlarmClock' : 'Clock'} size={20} />
            {m}:{s}
        </div>
    );
};

// ─── Roster Row ─────────────────────────────────────────────────────
const RosterRow = ({ student, courseId, sessionId, onMarkPresent, captains }) => {
    const [isMarking, setIsMarking] = useState(false);
    const { addToast } = useToast();

    const handleMarkPresent = async () => {
        if (student.isPresent) return;
        setIsMarking(true);
        try {
            await supabaseService.adminMarkStudentPresent({ userId: student.userId, courseId, sessionId });
            onMarkPresent(student.userId);
            addToast(`✅ ${student.fullName} marked present.`, 'success');
        } catch (err) {
            console.error('Admin mark present failed:', err);
            addToast(`Failed to mark present: ${err?.message || err}`, 'error');
        } finally {
            setIsMarking(false);
        }
    };

    return (
        <div className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${student.isPresent ? 'border-green-500/30 bg-green-500/5' : 'border-border bg-card hover:border-primary/30'}`}>
            <div className="w-9 h-9 rounded-full flex items-center justify-center text-sm font-black bg-muted shrink-0 overflow-hidden">
                {student.avatarUrl
                    ? <img src={student.avatarUrl} alt="" className="w-full h-full object-cover" />
                    : (student.fullName?.charAt(0) || '?')
                }
            </div>
            <div className="flex-1 min-w-0 flex items-center gap-2">
                <div className="min-w-0 flex-1">
                    <p className="font-bold text-sm truncate flex items-center gap-2">
                        {student.fullName}
                        {captains?.captain?.user_id === student.userId && (
                            <span title="Track Captain (Oldest)" className="bg-secondary/10 text-secondary border border-secondary/20 p-0.5 rounded-full inline-flex"><Icon name="Crown" size={12} /></span>
                        )}
                        {captains?.assistantCaptain?.user_id === student.userId && (
                            <span title="Assistant Captain (Youngest)" className="bg-primary/10 text-primary border border-primary/20 p-0.5 rounded-full inline-flex"><Icon name="Award" size={12} /></span>
                        )}
                    </p>
                    <p className="text-xs text-muted-foreground truncate">{student.email}</p>
                </div>
            </div>
            {student.isPresent ? (
                <div className="flex items-center gap-1.5 text-green-500 font-black text-xs">
                    <Icon name="CheckCircle2" size={16} />
                    <span className="hidden sm:inline">Present</span>
                </div>
            ) : (
                <button
                    onClick={handleMarkPresent}
                    disabled={isMarking}
                    className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-border text-xs font-bold hover:border-primary hover:text-primary transition-all disabled:opacity-50 shrink-0"
                >
                    {isMarking
                        ? <div className="w-3 h-3 border border-current border-t-transparent rounded-full animate-spin" />
                        : <Icon name="UserCheck" size={13} />
                    }
                    <span className="hidden sm:inline">Mark Present</span>
                </button>
            )}
        </div>
    );
};

// ─── Attendance Report Modal ──────────────────────────────────────────
const AttendanceReportModal = ({ session, isOpen, onClose }) => {
    const [roster, setRoster] = useState([]);
    const [captains, setCaptains] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    const [removingId, setRemovingId] = useState(null);
    const { addToast } = useToast();

    useEffect(() => {
        if (!isOpen || !session) return;
        
        const loadReport = async () => {
            setIsLoading(true);
            try {
                const [data, caps] = await Promise.all([
                    supabaseService.getCourseAttendanceRoster(session.course_id, session.id),
                    supabaseService.getTrackCaptains([session.course_id])
                ]);
                setRoster(data);
                setCaptains(caps);
            } catch (e) {
                console.error('Failed to load roster:', e);
            } finally {
                setIsLoading(false);
            }
        };

        loadReport();
    }, [isOpen, session]);

    const handleRemove = async (student) => {
        if (!window.confirm(`Remove attendance for ${student.fullName}?`)) return;
        setRemovingId(student.userId);
        try {
            await supabaseService.adminRemoveStudentAttendance({ userId: student.userId, sessionId: session.id });
            setRoster(prev => prev.map(r => r.userId === student.userId ? { ...r, isPresent: false } : r));
            addToast(`🗑️ Attendance removed for ${student.fullName}.`, 'success');
        } catch (err) {
            addToast(`Failed: ${err?.message || err}`, 'error');
        } finally {
            setRemovingId(null);
        }
    };

    const presentCount = roster.filter(r => r.isPresent).length;
    const totalCount = roster.length;
    const pct = totalCount > 0 ? Math.round((presentCount / totalCount) * 100) : 0;
    const courseTitle = session?.title?.replace('Attendance: ', '') || 'Course';
    
    // Sort absent first
    const sortedRoster = [...roster].sort((a, b) => Number(a.isPresent) - Number(b.isPresent));

    return (
        <Modal isOpen={isOpen} onClose={onClose} title="Attendance Report" maxWidth="max-w-2xl">
            {isLoading ? (
                <div className="flex items-center justify-center py-20">
                    <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
                </div>
            ) : (
                <div className="space-y-6">
                    {/* Summary */}
                    <div className="p-4 bg-muted border border-border rounded-xl flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                        <div>
                            <p className="text-sm font-bold text-muted-foreground uppercase tracking-widest mb-1">Session Summary</p>
                            <h4 className="font-black italic text-lg">{courseTitle}</h4>
                            <p className="text-sm text-muted-foreground mt-0.5">
                                Closed on {new Date(session?.end_time).toLocaleString()}
                            </p>
                        </div>
                        <div className="flex items-center gap-4 bg-card px-4 py-3 rounded-lg border border-border shrink-0">
                            <div className="text-center">
                                <p className="text-3xl font-black text-green-500">{pct}%</p>
                                <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">Attendance</p>
                            </div>
                            <div className="h-10 w-px bg-border"></div>
                            <div className="text-center">
                                <p className="text-xl font-bold">{presentCount} <span className="text-muted-foreground text-sm font-medium">/ {totalCount}</span></p>
                                <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">Students</p>
                            </div>
                        </div>
                    </div>

                    {/* Student List */}
                    <div className="space-y-2 max-h-[50vh] overflow-y-auto custom-scrollbar pr-1">
                        {sortedRoster.length === 0 ? (
                            <p className="text-center text-muted-foreground text-sm py-10">No students found.</p>
                        ) : sortedRoster.map(student => (
                            <div key={student.userId} className={`flex items-center gap-3 p-3 rounded-xl border ${student.isPresent ? 'border-green-500/30 bg-green-500/5' : 'border-red-500/30 bg-red-500/5'}`}>
                                <div className="w-9 h-9 rounded-full flex items-center justify-center text-sm font-black bg-muted shrink-0 overflow-hidden">
                                    {student.avatarUrl
                                        ? <img src={student.avatarUrl} alt="" className="w-full h-full object-cover" />
                                        : (student.fullName?.charAt(0) || '?')
                                    }
                                </div>
                                <div className="flex-1 min-w-0 flex items-center gap-2">
                                    <div className="min-w-0 flex-1">
                                        <p className="font-bold text-sm truncate flex items-center gap-2">
                                            {student.fullName}
                                            {captains?.captain?.user_id === student.userId && (
                                                <span title="Track Captain (Oldest)" className="bg-secondary/10 text-secondary border border-secondary/20 p-0.5 rounded-full inline-flex"><Icon name="Crown" size={12} /></span>
                                            )}
                                            {captains?.assistantCaptain?.user_id === student.userId && (
                                                <span title="Assistant Captain (Youngest)" className="bg-primary/10 text-primary border border-primary/20 p-0.5 rounded-full inline-flex"><Icon name="Award" size={12} /></span>
                                            )}
                                        </p>
                                        <p className="text-xs text-muted-foreground truncate">{student.email}</p>
                                    </div>
                                </div>
                                {student.isPresent ? (
                                    <div className="flex items-center gap-2 shrink-0">
                                        <div className="flex items-center gap-1.5 text-green-500 font-black text-xs px-3 py-1.5 bg-green-500/10 rounded-lg">
                                            <Icon name="CheckCircle2" size={16} />
                                            <span>Present</span>
                                        </div>
                                        <button
                                            onClick={() => handleRemove(student)}
                                            disabled={removingId === student.userId}
                                            title="Remove attendance"
                                            className="w-11 h-11 flex items-center justify-center rounded-lg border border-red-400/30 text-red-400 hover:bg-red-500/10 hover:border-red-400 transition-all disabled:opacity-50"
                                        >
                                            {removingId === student.userId
                                                ? <div className="w-3 h-3 border border-current border-t-transparent rounded-full animate-spin" />
                                                : <Icon name="Trash2" size={13} />
                                            }
                                        </button>
                                    </div>
                                ) : (
                                    <div className="flex items-center gap-1.5 text-red-500 font-bold text-xs px-3 py-1.5 bg-red-500/10 rounded-lg shrink-0">
                                        <Icon name="XCircle" size={16} />
                                        <span>Absent</span>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </Modal>
    );
};

const ActiveSessionCard = ({ session, onClose }) => {
    const [roster, setRoster] = useState([]);
    const [captains, setCaptains] = useState(null);
    const [isLoadingRoster, setIsLoadingRoster] = useState(true);
    const [isClosing, setIsClosing] = useState(false);
    const [codeCopied, setCodeCopied] = useState(false);
    const { addToast } = useToast();

    // Code is pulled from the session object directly (stored in Supabase, no localStorage)
    const plainCode = session._plainCode || session._meta?.plainCode || null;

    const handleCopyCode = () => {
        if (!plainCode) return;
        navigator.clipboard.writeText(plainCode).then(() => {
            setCodeCopied(true);
            setTimeout(() => setCodeCopied(false), 2000);
        });
    };

    const loadRoster = useCallback(async () => {
        try {
            const [data, caps] = await Promise.all([
                supabaseService.getCourseAttendanceRoster(session.course_id, session.id),
                supabaseService.getTrackCaptains([session.course_id])
            ]);
            setRoster(data);
            setCaptains(caps);
        } catch (e) {
            console.error('Failed to load roster:', e);
        } finally {
            setIsLoadingRoster(false);
        }
    }, [session.course_id, session.id]);

    useEffect(() => {
        loadRoster();
        
        const channel = supabaseService.client
            .channel(`roster_${session.id}`)
            .on(
                'postgres_changes',
                { event: 'INSERT', schema: 'public', table: 'lesson_progress', filter: `lesson_id=ilike.%${session.id}%` },
                () => { loadRoster(); }
            )
            .on(
                'postgres_changes',
                { event: 'UPDATE', schema: 'public', table: 'lesson_progress', filter: `lesson_id=ilike.%${session.id}%` },
                () => { loadRoster(); }
            )
            .subscribe();

        return () => {
            supabaseService.client.removeChannel(channel);
        };
    }, [loadRoster, session.id]);

    const presentCount = roster.filter(r => r.isPresent).length;
    const totalCount = roster.length;
    const pct = totalCount > 0 ? Math.round((presentCount / totalCount) * 100) : 0;

    const handleClose = async () => {
        if (!window.confirm('Close this attendance register now?')) return;
        setIsClosing(true);
        try {
            await supabaseService.closeCourseAttendance(session.id);
            addToast('Attendance register closed.', 'success');
            onClose(session.id);
        } catch (e) {
            addToast('Failed to close register.', 'error');
        } finally {
            setIsClosing(false);
        }
    };

    const handleMarkPresent = (userId) => {
        setRoster(prev => prev.map(r => r.userId === userId ? { ...r, isPresent: true } : r));
    };

    const courseTitle = session.title?.replace('Attendance: ', '') || 'Course';

    return (
        <div className="border border-green-500/40 bg-green-500/5 rounded-2xl overflow-hidden">
            {/* Header */}
            <div className="p-4 sm:p-5 border-b border-green-500/20 flex flex-col sm:flex-row sm:items-center gap-3">
                <div className="flex items-center gap-3 flex-1 min-w-0">
                    <div className="w-10 h-10 bg-green-500/20 text-green-600 rounded-xl flex items-center justify-center shrink-0 relative">
                        <Icon name="ClipboardCheck" size={20} />
                        <span className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full animate-ping" />
                    </div>
                    <div className="min-w-0">
                        <p className="font-black italic text-base truncate">{courseTitle}</p>
                        <div className="flex items-center gap-2 mt-0.5 flex-wrap">
                            <span className="text-xs font-bold text-green-600 bg-green-500/10 px-2 py-0.5 rounded-full">● LIVE</span>
                            <span className="text-xs text-muted-foreground">{presentCount}/{totalCount} present ({pct}%)</span>
                            {plainCode && (
                                <button
                                    onClick={handleCopyCode}
                                    title="Click to copy code"
                                    className="flex items-center gap-1.5 text-xs font-black bg-amber-500/20 text-amber-700 dark:text-amber-400 px-2 py-0.5 rounded-lg ml-1 border border-amber-500/30 tracking-widest hover:bg-amber-500/30 transition-colors"
                                >
                                    <Icon name={codeCopied ? 'Check' : 'Key'} size={12} />
                                    CODE: {plainCode}
                                </button>
                            )}
                            {!plainCode && (
                                <span className="text-xs text-muted-foreground/50 italic">(code not available — was this session created before crypto was added?)</span>
                            )}
                        </div>
                    </div>
                </div>
                <div className="flex items-center gap-3 shrink-0">
                    <Countdown endsAt={session.end_time} onExpire={() => onClose(session.id)} />
                    <Button
                        onClick={handleClose}
                        disabled={isClosing}
                        variant="outline"
                        className="text-red-500 border-red-500/30 hover:bg-red-500/10 text-xs h-9 px-3 gap-1.5"
                    >
                        <Icon name="X" size={13} /> Close
                    </Button>
                </div>
            </div>

            {/* Progress bar */}
            <div className="h-1.5 bg-muted">
                <div
                    className="h-full bg-green-500 transition-all duration-1000"
                    style={{ width: `${pct}%` }}
                />
            </div>

            {/* Roster */}
            <div className="p-4 sm:p-5">
                {isLoadingRoster ? (
                    <div className="flex items-center justify-center h-24">
                        <div className="w-6 h-6 border-2 border-primary border-t-transparent rounded-full animate-spin" />
                    </div>
                ) : roster.length === 0 ? (
                    <p className="text-center text-muted-foreground text-sm py-6">No enrolled students found for this course.</p>
                ) : (
                    <div className="space-y-2 max-h-72 overflow-y-auto custom-scrollbar pr-1">
                        {/* Sort: absent first */}
                        {[...roster].sort((a, b) => Number(a.isPresent) - Number(b.isPresent))
                            .map(student => (
                                <RosterRow
                                    key={student.userId}
                                    student={student}
                                    courseId={session.course_id}
                                    sessionId={session.id}
                                    onMarkPresent={handleMarkPresent}
                                    captains={captains}
                                />
                            ))}
                    </div>
                )}
            </div>
        </div>
    );
};

// ─── Main Component ──────────────────────────────────────────────────
const CourseAttendance = () => {
    const { user } = useSelector(state => state.auth);
    const { addToast } = useToast();

    // Pull all academy + vault courses from Redux (no extra fetch needed)
    const academy = useSelector(state => state.content.academy) || [];
    const vault   = useSelector(state => state.content.vault)   || [];
    const allCourses = [...academy, ...vault].filter(c => c && c.id && c.title);

    const [activeSessions, setActiveSessions] = useState([]);
    const [pastSessions, setPastSessions]     = useState([]);
    const [isLoading, setIsLoading]           = useState(true);
    const [isPastLoading, setIsPastLoading]   = useState(true);
    const [isOpening, setIsOpening]           = useState(false);
    
    // Modal state
    const [selectedPastSession, setSelectedPastSession] = useState(null);

    // Form state — now driven by course selector
    const [selectedCourseId, setSelectedCourseId] = useState('');
    const [duration, setDuration]                  = useState(15);
    const [search, setSearch]                      = useState('');
    const [dropdownOpen, setDropdownOpen]          = useState(false);
    const dropdownRef = useRef(null);

    const selectedCourse = allCourses.find(c => String(c.id) === selectedCourseId);

    // Close dropdown when clicking outside
    useEffect(() => {
        const handler = (e) => { if (!dropdownRef.current?.contains(e.target)) setDropdownOpen(false); };
        document.addEventListener('mousedown', handler);
        return () => document.removeEventListener('mousedown', handler);
    }, []);

    const filteredCourses = allCourses.filter(c =>
        !search || c.title?.toLowerCase().includes(search.toLowerCase()) || String(c.id).toLowerCase().includes(search.toLowerCase())
    );

    const loadActiveSessions = useCallback(async () => {
        try {
            const data = await supabaseService.getActiveCourseAttendances();
            setActiveSessions(data);
        } catch (e) {
            console.error('Failed to load active sessions:', e);
        } finally {
            setIsLoading(false);
        }
    }, []);

    const loadPastSessions = useCallback(async () => {
        try {
            const data = await supabaseService.getClosedCourseAttendances();
            setPastSessions(data);
        } catch (e) {
            console.error('Failed to load past sessions:', e);
        } finally {
            setIsPastLoading(false);
        }
    }, []);

    useEffect(() => {
        loadActiveSessions();
        loadPastSessions();
        const channel = supabaseService.client
            .channel('attendance_broadcasts_admin')
            .on('broadcast', { event: 'ATTENDANCE_OPENED' }, () => loadActiveSessions())
            .on('broadcast', { event: 'ATTENDANCE_CLOSED' }, () => {
                loadActiveSessions();
                loadPastSessions();
            })
            .subscribe();

        return () => supabaseService.client.removeChannel(channel);
    }, [loadActiveSessions, loadPastSessions]);

    const handleOpen = async () => {
        if (!selectedCourseId) {
            addToast('Please select a course first.', 'error');
            return;
        }
        if (duration < 1 || duration > 60) {
            addToast('Duration must be between 1 and 60 minutes.', 'error');
            return;
        }

        setIsOpening(true);
        try {
            const plainTextCode = generateAttendanceCode();
            const { hash, salt } = await hashAttendanceCode(plainTextCode);

            const sessionData = await supabaseService.openCourseAttendance({
                courseId: selectedCourseId,
                courseTitle: selectedCourse?.title || selectedCourseId,
                durationMinutes: Number(duration),
                openedBy: user?.id,
                codeHash: hash,
                codeSalt: salt,
                plainCode: plainTextCode,   // stored in DB description JSON
            });

            // Immediately inject the session with the plain-text code into state
            // No localStorage — code comes from Supabase via _meta.plainCode
            const enriched = {
                ...sessionData,
                course_id: selectedCourseId,
                _meta: { codeHash: hash, codeSalt: salt, courseId: selectedCourseId, plainCode: plainTextCode },
                _plainCode: plainTextCode,
            };
            setActiveSessions(prev => [enriched, ...prev]);

            addToast(`✅ Attendance opened! Code: ${plainTextCode}`, 'success');
            setSelectedCourseId('');
            setSearch('');
        } catch (e) {
            console.error('handleOpen error:', e);
            addToast(`Failed to open register: ${e?.message || e}`, 'error');
            // Fall back to reload in case the session was partially created
            loadActiveSessions();
        } finally {
            setIsOpening(false);
        }
    };

    const handleSessionClosed = (sessionId) => {
        setActiveSessions(prev => prev.filter(s => s.id !== sessionId));
        loadPastSessions(); // Refresh past sessions to include the newly closed one
    };

    return (
        <div className="space-y-6 p-4 md:p-6 overflow-hidden">
            {/* Header */}
            <div>
                <h2 className="text-xl sm:text-2xl font-black italic text-primary">Attendance Register</h2>
                <p className="text-sm text-muted-foreground mt-1">
                    Open a timed register for any course. Enrolled students are instantly notified and must mark themselves present before it auto-closes.
                </p>
            </div>

            {/* Open Register Form */}
            <div className="p-4 md:p-6 border border-border rounded-2xl bg-card space-y-5">
                <h3 className="font-black italic text-sm uppercase tracking-widest text-muted-foreground">Open New Register</h3>

                {/* Course Dropdown */}
                <div ref={dropdownRef} className="relative">
                    <label className="block text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1.5">
                        Select Course <span className="text-red-400">*</span>
                    </label>

                    {/* Trigger */}
                    <button
                        type="button"
                        onClick={() => setDropdownOpen(o => !o)}
                        className="w-full flex items-center justify-between px-4 py-3 bg-muted border border-border rounded-xl focus:ring-2 focus:ring-primary outline-none text-sm text-left transition-colors hover:border-primary/50"
                    >
                        {selectedCourse ? (
                            <div className="flex items-center gap-3 min-w-0">
                                {selectedCourse.image && (
                                    <img src={selectedCourse.image} alt="" className="w-8 h-8 rounded-lg object-cover shrink-0" />
                                )}
                                <div className="min-w-0">
                                    <p className="font-bold truncate">{selectedCourse.title}</p>
                                    <p className="text-xs text-muted-foreground font-mono truncate">ID: {selectedCourse.id}</p>
                                </div>
                            </div>
                        ) : (
                            <span className="text-muted-foreground">Choose a course…</span>
                        )}
                        <Icon name={dropdownOpen ? 'ChevronUp' : 'ChevronDown'} size={16} className="shrink-0 ml-2 text-muted-foreground" />
                    </button>

                    {/* Dropdown panel */}
                    {dropdownOpen && (
                        <div className="absolute z-30 top-full mt-1 left-0 right-0 bg-card border border-border rounded-2xl shadow-2xl overflow-hidden">
                            {/* Search */}
                            <div className="p-2 border-b border-border">
                                <div className="relative">
                                    <Icon name="Search" size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
                                    <input
                                        autoFocus
                                        type="text"
                                        placeholder="Search courses…"
                                        value={search}
                                        onChange={e => setSearch(e.target.value)}
                                        className="w-full pl-8 pr-3 py-2 bg-muted rounded-lg text-sm outline-none border border-border focus:border-primary"
                                    />
                                </div>
                            </div>

                            {/* List */}
                            <ul className="max-h-64 overflow-y-auto custom-scrollbar divide-y divide-border">
                                {filteredCourses.length === 0 ? (
                                    <li className="px-4 py-6 text-center text-sm text-muted-foreground">No courses found.</li>
                                ) : filteredCourses.map(course => (
                                    <li key={course.id}>
                                        <button
                                            type="button"
                                            onClick={() => {
                                                setSelectedCourseId(String(course.id));
                                                setDropdownOpen(false);
                                                setSearch('');
                                            }}
                                            className={`w-full flex items-center gap-3 px-4 py-3 hover:bg-muted transition-colors text-left ${String(course.id) === selectedCourseId ? 'bg-primary/5 text-primary' : ''}`}
                                        >
                                            {course.image ? (
                                                <img src={course.image} alt="" className="w-9 h-9 rounded-lg object-cover shrink-0" />
                                            ) : (
                                                <div className="w-9 h-9 rounded-lg bg-muted flex items-center justify-center shrink-0">
                                                    <Icon name="BookOpen" size={16} className="text-muted-foreground" />
                                                </div>
                                            )}
                                            <div className="flex-1 min-w-0">
                                                <p className="font-bold text-sm truncate">{course.title}</p>
                                                <p className="text-xs text-muted-foreground truncate">
                                                    {course.instructor || course.level || ''}{course.category ? ` · ${course.category}` : ''}
                                                </p>
                                            </div>
                                            {String(course.id) === selectedCourseId && (
                                                <Icon name="Check" size={15} className="text-primary shrink-0" />
                                            )}
                                        </button>
                                    </li>
                                ))}
                            </ul>

                            {allCourses.length === 0 && (
                                <div className="px-4 py-6 text-center text-sm text-muted-foreground">
                                    <Icon name="AlertCircle" size={24} className="mx-auto mb-2 opacity-40" />
                                    No courses loaded yet. Make sure the Academy has published content.
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* Duration Slider */}
                <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1.5">
                        Auto-Close After — <span className="text-primary">{duration} min</span>
                    </label>
                    <div className="flex items-center gap-4">
                        <input
                            type="range" min={1} max={60} value={duration}
                            onChange={e => setDuration(Number(e.target.value))}
                            className="flex-1 accent-primary"
                        />
                        <input
                            type="number" min={1} max={60} value={duration}
                            onChange={e => setDuration(Number(e.target.value))}
                            className="w-20 text-center px-2 py-2 bg-muted border border-border rounded-xl focus:ring-2 focus:ring-primary outline-none text-sm font-black"
                        />
                    </div>
                    <div className="flex gap-2 mt-2 flex-wrap">
                        {[5, 10, 15, 20, 30].map(t => (
                            <button
                                key={t}
                                onClick={() => setDuration(t)}
                                className={`px-3 py-1 rounded-lg text-xs font-bold border transition-all ${duration === t ? 'border-primary bg-primary/10 text-primary' : 'border-border hover:border-primary/40'}`}
                            >{t} min</button>
                        ))}
                    </div>
                </div>

                <Button
                    onClick={handleOpen}
                    disabled={isOpening || !selectedCourseId}
                    className="w-full sm:w-auto gap-2 bg-green-600 hover:bg-green-700 text-white disabled:opacity-50"
                    size="lg"
                >
                    {isOpening
                        ? <div className="w-5 h-5 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                        : <Icon name="ClipboardCheck" size={18} />
                    }
                    {isOpening ? 'Opening…' : 'Open Attendance Register'}
                </Button>
            </div>

            {/* Active Sessions */}
            <div className="space-y-3">
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                    <h3 className="font-black italic text-sm uppercase tracking-widest text-muted-foreground">
                        Active Registers
                        <span className={`ml-2 px-2 py-0.5 rounded-full text-xs ${activeSessions.length > 0 ? 'bg-green-500/20 text-green-600' : 'bg-muted text-muted-foreground'}`}>
                            {activeSessions.length}
                        </span>
                    </h3>
                    <button onClick={loadActiveSessions} className="text-xs text-muted-foreground hover:text-foreground flex items-center gap-1">
                        <Icon name="RefreshCcw" size={12} /> Refresh
                    </button>
                </div>

                {isLoading ? (
                    <div className="flex items-center justify-center h-24">
                        <div className="w-6 h-6 border-2 border-primary border-t-transparent rounded-full animate-spin" />
                    </div>
                ) : activeSessions.length === 0 ? (
                    <div className="text-center py-12 border border-dashed border-border rounded-2xl text-muted-foreground">
                        <Icon name="ClipboardX" size={36} className="mx-auto mb-3 opacity-30" />
                        <p className="font-bold">No active registers</p>
                        <p className="text-sm mt-1">Open one above to start taking attendance.</p>
                    </div>
                ) : (
                    <div className="space-y-4">
                        {activeSessions.map(session => (
                            <ActiveSessionCard
                                key={session.id}
                                session={session}
                                onClose={handleSessionClosed}
                            />
                        ))}
                    </div>
                )}
            </div>

            {/* Past Registers / History */}
            <div className="space-y-3 mt-10">
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                    <h3 className="font-black italic text-sm uppercase tracking-widest text-muted-foreground">
                        Past Registers
                        <span className={`ml-2 px-2 py-0.5 rounded-full text-xs ${pastSessions.length > 0 ? 'bg-muted text-foreground' : 'bg-muted text-muted-foreground'}`}>
                            {pastSessions.length}
                        </span>
                    </h3>
                    <button onClick={loadPastSessions} className="text-xs text-muted-foreground hover:text-foreground flex items-center gap-1">
                        <Icon name="RefreshCcw" size={12} /> Refresh
                    </button>
                </div>

                {isPastLoading ? (
                    <div className="flex items-center justify-center h-24">
                        <div className="w-6 h-6 border-2 border-primary border-t-transparent rounded-full animate-spin" />
                    </div>
                ) : pastSessions.length === 0 ? (
                    <div className="text-center py-8 border border-border rounded-2xl text-muted-foreground bg-card">
                        <Icon name="History" size={28} className="mx-auto mb-2 opacity-30" />
                        <p className="text-sm">No historical attendance records found.</p>
                    </div>
                ) : (
                    <div className="space-y-3">
                        {pastSessions.map(session => (
                            <div key={session.id} className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-4 border border-border bg-card rounded-xl hover:border-primary/30 transition-colors">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 bg-muted text-muted-foreground rounded-xl flex items-center justify-center shrink-0">
                                        <Icon name="ClipboardList" size={20} />
                                    </div>
                                    <div>
                                        <p className="font-bold text-sm">{session.title?.replace('Attendance: ', '') || 'Course'}</p>
                                        <p className="text-xs text-muted-foreground flex items-center gap-1.5 mt-0.5">
                                            <Icon name="Calendar" size={12} />
                                            {new Date(session.end_time).toLocaleDateString()} at {new Date(session.end_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                        </p>
                                    </div>
                                </div>
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => setSelectedPastSession(session)}
                                    className="shrink-0 w-full sm:w-auto gap-2"
                                >
                                    <Icon name="Eye" size={14} /> View Report
                                </Button>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Attendance Report Modal */}
            <AttendanceReportModal 
                isOpen={!!selectedPastSession} 
                session={selectedPastSession} 
                onClose={() => setSelectedPastSession(null)} 
            />
        </div>
    );
};

export default CourseAttendance;
